class AlertEngine:
    def __init__(self, config, now_fn=None):
        self.config = config
        self.now = now_fn or time.time
        self.alerts = {}
        self.order = deque()          # newest first
        self._debounce = {}
        self._open = {}            # (kind, subject) -> alert id
        self.suppressed = 0

    def enabled(self, kind):
        return bool(self.config.get(f"alerts.{kind}", True))

    def is_muted(self, kind, device_key, subject):
        muted = self.config.get("alerts.muted_devices", []) or []
        expected = self.config.get("alerts.expected", []) or []
        return (f"{kind}|{device_key}" in muted or
                f"{kind}|{subject}" in expected)

    def _add(self, kind, severity, device_key, reason, observed, interp, poss,
             confidence=None, why=None, evidence=None, refs=None,
             subject=None):
        if not self.enabled(kind):
            return None
        subject = subject or device_key
        if self.is_muted(kind, device_key, subject):
            self.suppressed += 1
            return None
        now = self.now()
        # same thing still happening and not acknowledged: update, don't spam
        oid = self._open.get((kind, subject))
        if oid and oid in self.alerts:
            a = self.alerts[oid]
            if not a.acknowledged and now - a.last_seen < 1800:
                a.count += 1
                a.last_seen = now
                a.observed = observed
                if evidence:
                    a.evidence = (a.evidence + list(evidence))[-20:]
                a.updated = True
                return a
        meta_conf, meta_why = ALERT_META.get(kind, ("Medium", ""))
        a = Alert(id=uuid.uuid4().hex[:8], kind=kind, severity=severity,
                  device_key=device_key, reason=reason, observed=observed,
                  interpretation=interp, possible_explanations=poss,
                  when=now, confidence=confidence or meta_conf,
                  why=why or meta_why, subject=subject, first_seen=now,
                  last_seen=now, evidence=list(evidence or [])[:20],
                  refs=dict(refs or {}))
        if device_key and not a.refs.get("device") and \
                not device_key.startswith("ip:"):
            a.refs["device"] = device_key
        self.alerts[a.id] = a
        self.order.appendleft(a.id)
        self._open[(kind, subject)] = a.id
        while len(self.order) > 500:
            self.alerts.pop(self.order.pop(), None)
        return a

    def _debounced(self, key, seconds):
        now = self.now()
        last = self._debounce.get(key)
        if last is not None and now - last < seconds:
            return True
        self._debounce[key] = now
        return False

    def acknowledge(self, aid):
        a = self.alerts.get(aid)
        if a:
            a.acknowledged = True
        return a

    def counts(self, include_ack=False):
        c = Counter()
        for aid in self.order:
            a = self.alerts.get(aid)
            if a and (include_ack or not a.acknowledged):
                c[a.severity] += 1
        return c

    def new_device(self, dev):
        if dev.expected:
            return None
        return self._add(
            "new_device", "INFO", dev.key,
            f"{dev.display_name()} joined your network",
            f"A device with {dev.confidence.lower()}-confidence identity "
            f"evidence ({', '.join(dev.evidence_summary()) or 'minimal'}) "
            f"appeared.",
            "This is a new local device on your network.",
            "Normal if you just added a device (phone, guest, smart-home "
            "gadget). Worth checking if you don't recognize it.")

    def gateway_change(self, gw_ip, n_macs):
        if self._debounced(f"gw:{gw_ip}", 120):
            return None
        return self._add(
            "gateway_change", "WARNING", f"ip:{gw_ip}",
            "Your router's MAC address changed",
            f"Your gateway ({gw_ip}) has answered ARP from {n_macs} "
            f"different MAC addresses in this session.",
            "The device claiming to be your router is not consistent.",
            "Often normal right after a router reboot or firmware update. "
            "It is also the classic sign of ARP spoofing \u2014 a device "
            "pretending to be your router. If you didn't just restart "
            "your router, investigate.")

    def duplicate_ip(self, ip, n_macs):
        if self._debounced(f"dupip:{ip}", 120):
            return None
        return self._add(
            "duplicate_ip", "WARNING", f"ip:{ip}",
            f"{ip} has answered from more than one device",
            f"{n_macs} different MAC addresses have claimed {ip}.",
            "Two devices currently disagree about who owns this address.",
            "Often harmless \u2014 Wi-Fi privacy MAC rotation or a device "
            "reconnecting and briefly overlapping the old lease. Worth a "
            "look if it keeps happening.")

    def dhcp_anomaly(self, servers):
        if self._debounced("dhcp_anomaly", 300):
            return None
        return self._add(
            "dhcp_anomaly", "WARNING", "",
            "More than one device is handing out IP addresses",
            f"{len(servers)} different DHCP servers seen: "
            f"{', '.join(sorted(servers))}.",
            "Normally only your router does this.",
            "Could be a second router plugged in by mistake, or \u2014 "
            "less commonly \u2014 a rogue DHCP server. If you don't "
            "recognize one of these addresses, unplug that device and "
            "check your network.")

    def rogue_ra(self, mac, who, prefixes, routers):
        if self._debounced(f"rogue_ra:{mac}", 600):
            return None
        return self._add(
            "rogue_ra", "WARNING", mac,
            f"{who} announced itself as an IPv6 router",
            f"An IPv6 Router Advertisement came from {mac}"
            f"{(' for ' + ', '.join(prefixes[:3])) if prefixes else ''}. "
            f"Routers announcing on this network: {', '.join(routers)}.",
            "Devices that accept this announcement may send IPv6 traffic "
            "through that device.",
            "Mesh Wi-Fi nodes, a second router, a phone hotspot or a "
            "virtual-machine host can do this legitimately.",
            evidence=[f"RA from {mac}"] + [f"prefix {p}" for p in
                                           prefixes[:4]],
            subject=f"rogue_ra:{mac}")

    def arp_spoof(self, ip, n_macs, flips, is_gateway):
        if self._debounced(f"arpspoof:{ip}", 120):
            return None
        who = "Your router's address" if is_gateway else f"The address {ip}"
        return self._add(
            "arp_spoof", "DANGER", f"ip:{ip}",
            f"{who} keeps switching between devices",
            f"{ip} was claimed by {n_macs} different MAC addresses and "
            f"flipped back and forth {flips} times within a minute.",
            "Two devices are repeatedly fighting over the same network "
            "address.",
            "A device normally answers for its address consistently. Rapid "
            "flip-flopping is the signature of ARP spoofing \u2014 one "
            "device impersonating another so traffic passes through it. It "
            "can also happen if two devices were accidentally given the "
            "same fixed IP. If this is your router's address, treat it "
            "seriously: disconnect and check the router's device list.")

    def chatty_device(self, dev):
        if self._debounced(f"chatty:{dev.key}", 600):
            return None
        return self._add(
            "chatty_device", "WARNING", dev.key,
            f"{dev.display_name()} is unusually active right now",
            "This device's traffic this minute is well above its own "
            "recent average.",
            "Its behavior changed compared to its own baseline this "
            "session.",
            "Often normal \u2014 a big download, a video call, a software "
            "update. Worth a glance if you don't expect that device to be "
            "busy right now.")

    def unknown_device(self, dev):
        if self._debounced(f"unknown:{dev.key}", 600):
            return None
        return self._add(
            "unknown_device", "WARNING", dev.key,
            f"{dev.display_name()} has very little identifying information",
            f"Only {', '.join(dev.evidence_summary()) or 'minimal'} "
            f"evidence is available for this device.",
            "MiniWireshark can't confidently say what this device is.",
            "Common for devices that stay quiet or use a randomized MAC. "
            "Confidence usually improves the longer it's on the network.")

    def reconnect_cycle(self, dev, n, window_s):
        if self._debounced(f"reconnect:{dev.key}", 600):
            return None
        return self._add(
            "reconnect_cycle", "WARNING", dev.key,
            f"{dev.display_name()} has joined/left {n} times recently",
            f"{n} reconnects in the last {int(window_s / 60)} minutes.",
            "This device is repeatedly reconnecting.",
            "Usually Wi-Fi interference, a weak signal, or a device with "
            "power-saving/roaming quirks \u2014 rarely an attack.")


    # ---- 3.0 detections (all phrased as anomalies) -----------------------
    def dns_server_change(self, dev_name, dev_key, old, new):
        if self._debounced(f"dnschg:{dev_key}:{new}", 1800):
            return None
        return self._add(
            "dns_server_change", "WARNING", dev_key,
            f"{dev_name} switched to a different DNS server",
            f"It had been using {old} for its lookups and is now using "
            f"{new}.",
            "The service that turns website names into addresses changed "
            "for this device.",
            "Common and harmless when a VPN connects, a browser enables "
            "secure DNS, or you change settings. Worth checking if you "
            "didn't change anything, because DNS decides which servers "
            "your device talks to.",
            confidence="Medium",
            why="This device consistently used one DNS server, then moved "
                "to another.",
            evidence=[f"Previous server: {old}", f"New server: {new}"],
            subject=f"{dev_key}|{new}")

    def dns_failures(self, rate, n, servers):
        if self._debounced("dnsfail", 900):
            return None
        return self._add(
            "dns_failures", "WARNING", "",
            "Many website lookups are failing",
            f"{rate:.0%} of the last {n} DNS lookups failed or got no "
            f"answer (servers: {', '.join(servers) or 'unknown'}).",
            "Website names aren't being resolved reliably right now.",
            "Often a temporary problem at your Internet provider or router, "
            "or an ad-blocker deliberately refusing some names.",
            confidence="Medium" if n >= 40 else "Low",
            why="The share of failed lookups is well above normal.",
            subject="dns")

    def dns_slow(self, median_ms, n, server):
        if self._debounced("dnsslow", 1800):
            return None
        return self._add(
            "dns_slow", "WARNING", "",
            "Website lookups are slow",
            f"The typical DNS answer took {median_ms:.0f} ms over the last "
            f"{n} lookups ({server or 'various servers'}).",
            "Pages may feel slow to start loading.",
            "Usually your provider's DNS being slow or a congested "
            "connection; it isn't a security problem.",
            confidence="Medium", why="Median DNS latency exceeded the "
                                     "slow-DNS threshold.",
            subject="dns")

    def dns_multi(self, servers):
        if self._debounced("dnsmulti", 3600):
            return None
        return self._add(
            "dns_multi", "INFO", "",
            f"{len(servers)} different DNS servers are in use",
            f"Lookups went to: {', '.join(sorted(servers)[:8])}.",
            "Devices on your network don't all use the same DNS service.",
            "Normal with VPNs, browsers that use their own secure DNS, or "
            "gadgets with hard-coded DNS. Public DNS services are not "
            "harmful in themselves.",
            confidence="High", why="More than three DNS servers were "
                                   "contacted.",
            subject="dnsmulti")

    def baseline_anomaly(self, dev, feature, value, mean):
        kind = {"bytes_up": "upload_spike", "bytes_down": "download_spike",
                "destinations": "many_destinations",
                "new_conns": "many_connections"}.get(feature)
        if not kind or self._debounced(f"{kind}:{dev.key}", 1800):
            return None
        label = {"bytes_up": ("uploaded", _human_bytes(value),
                              _human_bytes(mean)),
                 "bytes_down": ("downloaded", _human_bytes(value),
                                _human_bytes(mean)),
                 "destinations": ("contacted", f"{int(value)} different "
                                  f"Internet hosts", f"{mean:.0f}"),
                 "new_conns": ("opened", f"{int(value)} new connections",
                               f"{mean:.0f}")}[feature]
        title = ALERT_TYPES[kind][0]
        return self._add(
            kind, ALERT_TYPES[kind][1], dev.key,
            f"{dev.display_name()}: {title.lower()}",
            f"In one minute it {label[0]} {label[1]}; its usual minute is "
            f"about {label[2]}.",
            "This behavior is unusual compared with this device's recent "
            "activity.",
            "Updates, backups, video calls, game downloads and cloud sync "
            "all cause bursts like this. It only matters if the device "
            "shouldn't be doing anything right now.",
            confidence="Medium",
            why="Compared with this device's own learned baseline (not "
                "with other devices).",
            evidence=[f"This minute: {label[1]}", f"Usual: {label[2]}"])

    def tcp_resets(self, dev, n, window_s, top_remote):
        if self._debounced(f"rst:{dev.key}", 1800):
            return None
        return self._add(
            "tcp_resets", "WARNING", dev.key,
            f"{dev.display_name()}: many connections are being reset",
            f"{n} connections were abruptly reset in the last "
            f"{int(window_s / 60)} minutes" +
            (f" (most often with {top_remote})." if top_remote else "."),
            "Connections are being refused or cut off.",
            "Often a service that's down, a firewall/ad-blocker refusing "
            "connections, or a flaky connection. Rarely a security issue.",
            confidence="Medium", why="The reset count crossed the "
                                     "threshold for this window.")

    def new_service(self, dev, service):
        if self._debounced(f"svc:{dev.key}:{service}", 86400):
            return None
        desc = service_description(service)
        return self._add(
            "new_service", "INFO", dev.key,
            f"{dev.display_name()} started advertising “{service}”",
            f"A device I already knew began announcing a new network "
            f"service: {service}." + (f" {desc}" if desc else ""),
            "This device now offers something new on your network.",
            "Normal after enabling sharing, casting or a new app. Worth a "
            "look only if you didn't change anything.",
            confidence="High", why="A known device advertised a service it "
                                   "hadn't advertised before.",
            subject=f"{dev.key}|{service}")

    def cleartext(self, dev_name, dev_key, proto, remote, is_public):
        if self._debounced(f"clear:{dev_key}:{proto}", 3600):
            return None
        sev = "WARNING" if proto in ("TELNET", "FTP", "POP3", "IMAP") and \
            is_public else "INFO"
        return self._add(
            "cleartext", sev, dev_key,
            f"{dev_name} used an unencrypted protocol ({proto})",
            f"Unencrypted {proto} traffic with {remote} was observed.",
            "Anyone on the same network path could read this traffic.",
            "Common for old devices, local printers and some smart-home "
            "gear. It's worth avoiding for anything with a password.",
            confidence="High", why="The protocol was recognised from the "
                                   "traffic itself.",
            subject=f"{dev_key}|{proto}")

    def remote_access(self, dev_name, dev_key, service, how):
        if self._debounced(f"ra:{dev_key}:{service}", 86400):
            return None
        return self._add(
            "remote_access", "WARNING", dev_key,
            f"{dev_name} offers remote access ({service})",
            f"{how}",
            "This device can probably be controlled over the network.",
            "Fine if you set it up (e.g. SSH on a Raspberry Pi, Remote "
            "Desktop on your PC). Make sure it's intended and protected "
            "by a strong password.",
            confidence="Medium", why="A remote-access service was "
                                     "advertised or accepted connections.",
            subject=f"{dev_key}|{service}")

    def new_country(self, dev, country, remote):
        if self._debounced(f"cc:{dev.key}:{country}", 86400):
            return None
        return self._add(
            "new_country", "INFO", dev.key,
            f"{dev.display_name()} contacted a new country ({country})",
            f"It connected to {remote}, located in {country} (per the "
            f"lookup database), after its usual destinations were learned.",
            "A destination country this device hadn't used this session.",
            "Very often normal: cloud and content services are spread "
            "across many countries. Location databases can also be wrong.",
            confidence="Low", why="New country after the baseline period.",
            subject=f"{dev.key}|{country}")

    def broadcast_storm(self, pps, top):
        if self._debounced("bstorm", 1800):
            return None
        return self._add(
            "broadcast_storm", "WARNING", "",
            "A lot of broadcast/multicast traffic",
            f"About {pps:.0f} broadcast/multicast packets per second" +
            (f", mostly from {top}." if top else "."),
            "The local network is being flooded with 'to everyone' "
            "messages.",
            "Can be a misbehaving gadget, a network loop (a cable plugged "
            "into two switch ports), or heavy discovery traffic.",
            confidence="Medium", why="Broadcast rate stayed above the "
                                     "threshold.",
            subject="bstorm")

    def scan_pattern(self, dev, what, n):
        if self._debounced(f"scan:{dev.key}", 3600):
            return None
        return self._add(
            "scan_pattern", "WARNING", dev.key,
            f"{dev.display_name()} shows a scanning-like pattern",
            f"Within a minute it tried {n} {what}, most without an answer.",
            "This looks like what network-scanning tools do.",
            "Expected if you run a scanner (or IT tools, printers/NAS "
            "discovery) on purpose. Otherwise, check what software the "
            "device runs.",
            confidence="Medium", why="Many distinct connection attempts "
                                     "with few successful replies.")


# ============================================================================
#  This computer's Wi-Fi link (read-only questions to the operating system)
# ============================================================================
def wifi_channel_from_mhz(mhz):
    try:
        f = int(round(float(mhz)))
    except (TypeError, ValueError):
        return None, ""
    if f == 2484:
        return 14, "2.4 GHz"
    if 2412 <= f <= 2472:
        return (f - 2407) // 5, "2.4 GHz"
    if 5150 <= f <= 5895:
        return (f - 5000) // 5, "5 GHz"
    if 5925 <= f <= 7125:
        return (f - 5950) // 5, "6 GHz"
    return None, ""


def _num(text):
    try:
        return float(str(text).replace(",", ".").strip())
    except (TypeError, ValueError):
        return None


def parse_netsh_wlan(text, want=""):
    """`netsh wlan show interfaces` (English, French or Spanish Windows).
    `want` = adapter name or description to prefer."""
    blocks, cur = [], {}
    for line in (text or "").splitlines():
        if ":" not in line:
            if cur and not line.strip():
                continue
            continue
        k, _sep, v = line.partition(":")
        k, v = k.strip().lower(), v.strip()
        if k in ("name", "nom", "nombre") and cur.get("name"):
            blocks.append(cur)
            cur = {}
        cur[k] = v
        if k in ("name", "nom", "nombre"):
            cur["name"] = v
    if cur:
        blocks.append(cur)

    def pick(b, *keys):
        for key, val in b.items():
            for k in keys:
                if key.startswith(k):
                    return val
        return ""
    best = None
    for b in blocks:
        state = pick(b, "state", "état", "etat", "estado").lower()
        ok = state.startswith(("connected", "connect", "conectado"))
        desc = pick(b, "description", "descripción", "descripcion")
        if want and (want == b.get("name") or want == desc):
            best = b if ok else best
            if ok:
                break
        if ok and best is None:
            best = b
    if best is None:
        return None
    b = best
    sig = re.search(r"(\d+)\s*%", pick(b, "signal", "señal", "senal"))
    rssi = _num(pick(b, "rssi"))
    pct = int(sig.group(1)) if sig else None
    if rssi is None and pct is not None:
        rssi = pct / 2.0 - 100.0          # Windows' own mapping
    ch = _num(pick(b, "channel", "canal"))
    band = pick(b, "band", "bande", "banda")
    return {"source": "netsh", "iface": b.get("name", ""),
            "ssid": pick(b, "ssid"),
            "bssid": pick(b, "ap bssid", "bssid", "bssid del punto",
                          "bssid du point").lower(),
            "rssi": rssi, "signal_pct": pct,
            "rx_mbps": _num(pick(b, "receive rate", "réception",
                                 "reception", "velocidad de recepción",
                                 "velocidad de recepcion")),
            "tx_mbps": _num(pick(b, "transmit rate", "transmission",
                                 "velocidad de transmisión",
                                 "velocidad de transmision")),
            "channel": int(ch) if ch is not None else None,
            "band": band or ("2.4 GHz" if ch and ch <= 14 else
                             "5 GHz" if ch else ""),
            "standard": pick(b, "radio type", "type de radio",
                             "tipo de radio")}


def parse_iw_link(text, iface=""):
    """`iw dev <iface> link` (Linux)."""
    text = text or ""
    if "Not connected" in text or "Connected to" not in text:
        return None
    m = re.search(r"Connected to ([0-9a-fA-F:]{17})", text)
    out = {"source": "iw", "iface": iface, "ssid": "", "rssi": None,
           "signal_pct": None, "rx_mbps": None, "tx_mbps": None,
           "channel": None, "band": "", "standard": "",
           "bssid": m.group(1).lower() if m else ""}
    for line in text.splitlines():
        k, _s, v = line.strip().partition(":")
        k, v = k.strip().lower(), v.strip()
        if k == "ssid":
            out["ssid"] = v
        elif k == "freq":
            out["channel"], out["band"] = wifi_channel_from_mhz(v)
        elif k == "signal":
            out["rssi"] = _num(v.split()[0]) if v else None
        elif k in ("rx bitrate", "tx bitrate") and v:
            rate = _num(v.split()[0])
            out["rx_mbps" if k.startswith("rx") else "tx_mbps"] = rate
            for std, tag in (("802.11be", "EHT"), ("802.11ax", "HE"),
                             ("802.11ac", "VHT"), ("802.11n", "MCS")):
                if tag in v and not out["standard"]:
                    out["standard"] = std
    return out


def parse_proc_wireless(text, iface=""):
    """/proc/net/wireless (Linux, when `iw` is missing): signal only."""
    for line in (text or "").splitlines()[2:]:
        name, _s, rest = line.partition(":")
        name = name.strip()
        if iface and name != iface:
            continue
        parts = rest.split()
        if len(parts) >= 3:
            level = _num(parts[2].rstrip("."))
            if level is None:
                continue
            if level > 0:                 # some drivers report 0..100
                level = level / 2.0 - 100.0
            return {"source": "/proc/net/wireless", "iface": name,
                    "ssid": "", "bssid": "", "rssi": level,
                    "signal_pct": None, "rx_mbps": None, "tx_mbps": None,
                    "channel": None, "band": "", "standard": ""}
    return None


def parse_macos_airport(text):
    """`system_profiler SPAirPortDataType` (macOS)."""
    text = text or ""
    i = text.find("Current Network Information:")
    if i < 0:
        return None
    block = text[i:].splitlines()[1:]
    out = {"source": "system_profiler", "iface": "", "ssid": "",
           "bssid": "", "rssi": None, "signal_pct": None, "rx_mbps": None,
           "tx_mbps": None, "channel": None, "band": "", "standard": ""}
    if block:
        out["ssid"] = block[0].strip().rstrip(":")
    for line in block[1:30]:
        k, _s, v = line.strip().partition(":")
        k, v = k.strip().lower(), v.strip()
        if not v and k.endswith("information"):
            break
        if k == "signal / noise":
            m = re.match(r"(-?\d+)\s*dBm\s*/\s*(-?\d+)", v)
            if m:
                out["rssi"] = float(m.group(1))
                out["noise"] = float(m.group(2))
        elif k == "channel":
            m = re.match(r"(\d+)\s*\(([\d.]+)\s*GHz", v)
            if m:
                out["channel"] = int(m.group(1))
                out["band"] = f"{m.group(2)} GHz"
        elif k == "transmit rate":
            out["tx_mbps"] = _num(v)
        elif k == "phy mode":
            out["standard"] = v
    return out


def wifi_quality(rssi):
    """→ (health status, word, plain-English explanation)."""
    if rssi is None:
        return "Unknown", "unknown", "Signal strength not reported."
    if rssi >= -60:
        return "Healthy", "excellent", "Strong signal."
    if rssi >= -67:
        return "Healthy", "good", "Good signal."
    if rssi >= -75:
        return "Degraded", "fair", ("Usable, but video calls and big "
                                    "downloads may stutter.")
    return "Needs attention", "weak", ("Weak signal — the most likely cause "
                                       "of slowness. Move closer to the "
                                       "router or remove obstacles.")


class WifiProbe:
    """Asks the operating system about THIS computer's Wi-Fi link every
    `interval` seconds, in the background. Read-only: nothing is sent on
    the network and no setting is changed."""

    def __init__(self, interval=30):
        self.interval = interval
        self.last = None
        self.at = 0.0
        self.busy = False
        self.error = ""
        self.history = deque(maxlen=240)     # (ts, rssi)
        self.seq = 0

    @staticmethod
    def _cmd(cmd, timeout=10):
        try:
            r = subprocess.run(cmd, capture_output=True, text=True,
                               timeout=timeout,
                               creationflags=getattr(
                                   subprocess, "CREATE_NO_WINDOW", 0))
            return r.stdout or ""
        except (OSError, subprocess.SubprocessError):
            return ""

    def read(self, iface="", desc=""):
        if IS_WINDOWS:
            return parse_netsh_wlan(self._cmd(["netsh", "wlan", "show",
                                               "interfaces"]), desc or iface)
        if sys.platform == "darwin":
            return parse_macos_airport(self._cmd(
                ["system_profiler", "SPAirPortDataType"], 30))
        names = [iface] if iface and os.path.isdir(
            f"/sys/class/net/{iface}/wireless") else [
            n for n in sorted(os.listdir("/sys/class/net"))
            if os.path.isdir(f"/sys/class/net/{n}/wireless")] \
            if os.path.isdir("/sys/class/net") else []
        for name in names:
            if shutil.which("iw"):
                got = parse_iw_link(self._cmd(["iw", "dev", name, "link"]),
                                    name)
                if got:
                    return got
            try:
                with open("/proc/net/wireless", encoding="utf-8") as f:
                    got = parse_proc_wireless(f.read(), name)
            except OSError:
                got = None
            if got:
                return got
        return None

    def refresh(self, iface="", desc="", force=False):
        if self.busy or (not force and time.time() - self.at <
                         self.interval):
            return False
        self.busy = True
        self.at = time.time()

        def work():
            try:
                got = self.read(iface, desc)
                self.error = ""
            except Exception as e:                   # noqa: BLE001
                got, self.error = None, str(e)
            self.last = got
            if got and got.get("rssi") is not None:
                self.history.append((time.time(), got["rssi"]))
            self.seq += 1
            self.busy = False
        threading.Thread(target=work, daemon=True, name="wifi-probe").start()
        return True

    def summary(self):
        w = self.last
        if not w:
            return None
        status, word, why = wifi_quality(w.get("rssi"))
        parts = []
        if w.get("rssi") is not None:
            parts.append(f"{w['rssi']:.0f} dBm ({word})")
        if w.get("tx_mbps") or w.get("rx_mbps"):
            parts.append(f"link {w.get('rx_mbps') or w.get('tx_mbps'):.0f} "
                         f"Mbit/s")
        if w.get("channel"):
            parts.append(f"channel {w['channel']}"
                         + (f" ({w['band']})" if w.get("band") else ""))
        if w.get("standard"):
            parts.append(w["standard"])
        return status, word, why, ", ".join(parts)


# ---- DNS health / intelligence ---------------------------------------------
# Lookup-time buckets (upper edges, ms) for the per-resolver histogram.
DNS_BUCKETS = (10, 25, 50, 100, 250, 500, 1000, float("inf"))
DNS_BUCKET_LABELS = ("<10", "10–25", "25–50", "50–100", "100–250",
                     "250–500", "0.5–1 s", ">1 s")


def dns_bucket(ms):
    for i, edge in enumerate(DNS_BUCKETS):
        if ms < edge:
            return i
    return len(DNS_BUCKETS) - 1


class DnsTracker:
    """Matches DNS queries to responses (latency), counts failures per
    server, tracks which server each device uses, and notices changes.
    Bounded everywhere."""

    def __init__(self):
        self.servers = {}
        self.pending = OrderedDict()
        self.domains = Counter()
        self.device_servers = defaultdict(Counter)
        self.device_last = {}           # dev_key -> (server, since_ts)
        self.recent = deque(maxlen=400)  # (ts, ok)
        self.latencies = deque(maxlen=200)
        self.slow = deque(maxlen=40)
        self.queries = self.responses = self.nxdomain = self.servfail = 0
        self.timeouts = 0
        self.encrypted_seen = Counter()   # provider/method -> count
        self.dot_flows = 0

    def _srv(self, ip):
        s = self.servers.get(ip)
        if s is None:
            s = self.servers[ip] = {"queries": 0, "responses": 0, "nx": 0,
                                    "servfail": 0, "timeouts": 0,
                                    "lat": deque(maxlen=60), "first": 0.0,
                                    "last": 0.0, "clients": set(),
                                    "hist": [0] * len(DNS_BUCKETS)}
        return s

    def on_query(self, ts, client_ip, server_ip, info, dev_key=""):
        self.queries += 1
        s = self._srv(server_ip)
        s["queries"] += 1
        s["first"] = s["first"] or ts
        s["last"] = ts
        if len(s["clients"]) < 200 and dev_key:
            s["clients"].add(dev_key)
        q = (info.get("qname") or "").lower()
        if q:
            self.domains[q] += 1
            if len(self.domains) > 8000:
                self.domains = Counter(dict(self.domains.most_common(4000)))
        key = (client_ip, server_ip, info.get("id"), q)
        self.pending[key] = (ts, dev_key)
        while len(self.pending) > 4096:
            self.pending.popitem(last=False)
        change = None
        if dev_key:
            c = self.device_servers[dev_key]
            c[server_ip] += 1
            last = self.device_last.get(dev_key)
            if last is None:
                self.device_last[dev_key] = (server_ip, ts, 1)
            elif last[0] == server_ip:
                self.device_last[dev_key] = (server_ip, last[1], last[2] + 1)
            else:
                # a change only counts if the old server was well
                # established and the new one is used consistently
                prev_total = c[last[0]]
                if prev_total >= 20 and c[server_ip] >= 10:
                    change = (last[0], server_ip)
                    self.device_last[dev_key] = (server_ip, ts, 1)
        return change

    def on_response(self, ts, client_ip, server_ip, info):
        self.responses += 1
        s = self._srv(server_ip)
        s["responses"] += 1
        s["last"] = ts
        rc = info.get("rcode", 0)
        if rc == 3:
            self.nxdomain += 1
            s["nx"] += 1
        elif rc == 2:
            self.servfail += 1
            s["servfail"] += 1
        key = (client_ip, server_ip, info.get("id"),
               (info.get("qname") or "").lower())
        ent = self.pending.pop(key, None)
        ok = rc in (0, 3)
        self.recent.append((ts, ok))
        if ent is None:
            return None
        ms = max(0.0, (ts - ent[0]) * 1000.0)
        s["lat"].append(ms)
        s["hist"][dns_bucket(ms)] += 1
        self.latencies.append((ts, ms))
        if ms > 1000:
            self.slow.append((info.get("qname", ""), ms, ts, server_ip))
        return ms

    def expire(self, now, timeout=5.0):
        n = 0
        for key in list(self.pending)[:2048]:
            ts, _dk = self.pending[key]
            if now - ts > timeout:
                self.pending.pop(key, None)
                srv = self.servers.get(key[1])
                if srv:
                    srv["timeouts"] += 1
                self.timeouts += 1
                self.recent.append((ts, False))
                n += 1
            else:
                break
        return n

    def failure_rate(self, now, window=300):
        rows = [ok for ts, ok in self.recent if now - ts <= window]
        if not rows:
            return 0.0, 0
        return 1.0 - (sum(rows) / len(rows)), len(rows)

    def median_latency(self, now=None, window=300):
        vals = [ms for ts, ms in self.latencies
                if now is None or now - ts <= window]
        return (statistics.median(vals), len(vals)) if vals else (None, 0)

    def histogram(self, server=None):
        """Lookup-time counts per DNS_BUCKETS (all servers or one)."""
        out = [0] * len(DNS_BUCKETS)
        for ip, s in self.servers.items():
            if server and ip != server:
                continue
            for i, n in enumerate(s.get("hist") or ()):
                out[i] += n
        return out

    def summary_rows(self):
        out = []
        for ip, s in sorted(self.servers.items(),
                            key=lambda kv: -kv[1]["queries"]):
            lat = statistics.median(s["lat"]) if s["lat"] else None
            out.append((ip, s["queries"], s["responses"], s["nx"],
                        s["servfail"] + s["timeouts"], lat))
        return out

    def to_dict(self):
        return {"servers": {ip: {k: (list(v) if isinstance(v, (deque, set))
                                     else v) for k, v in s.items()}
                            for ip, s in list(self.servers.items())[:50]},
                "top_domains": self.domains.most_common(100),
                "queries": self.queries, "responses": self.responses,
                "nxdomain": self.nxdomain, "servfail": self.servfail,
                "timeouts": self.timeouts,
                "encrypted": dict(self.encrypted_seen)}

    def load(self, d):
        if not isinstance(d, dict):
            return
        for k in ("queries", "responses", "nxdomain", "servfail",
                  "timeouts"):
            setattr(self, k, int(d.get(k, 0) or 0))
        for ip, s in (d.get("servers") or {}).items():
            srv = self._srv(ip)
            for k in ("queries", "responses", "nx", "servfail", "timeouts"):
                srv[k] = int(s.get(k, 0) or 0)
            srv["lat"].extend(float(x) for x in (s.get("lat") or [])[-60:])
            srv["first"] = float(s.get("first") or 0)
            srv["last"] = float(s.get("last") or 0)
            hist = s.get("hist") or []
            if isinstance(hist, list) and len(hist) == len(DNS_BUCKETS):
                srv["hist"] = [int(x or 0) for x in hist]
        for name, n in d.get("top_domains") or []:
            self.domains[name] = n
        self.encrypted_seen.update(d.get("encrypted") or {})


# ---- per-device behavioral baseline -----------------------------------------
class DeviceBaseline:
    """Lightweight statistics (no ML): exponentially-weighted mean/variance
    of per-minute features over this device's ACTIVE minutes, plus its
    usual hours, protocols, services and countries."""

    FEATURES = ("packets", "bytes_up", "bytes_down", "destinations",
                "dns", "new_conns")
    ALPHA = 0.05

    def __init__(self):
        self.n = 0
        self.mean = {f: 0.0 for f in self.FEATURES}
        self.var = {f: 0.0 for f in self.FEATURES}
        self.hours = [0] * 24
        self.protocols = Counter()
        self.services = Counter()
        self.countries = set()
        self.cur_min = None
        self.cur = None
        self.cur_dests = set()

    def _reset_cur(self, minute):
        self.cur_min = minute
        self.cur = {f: 0 for f in self.FEATURES}
        self.cur_dests = set()

    def observe(self, ts, nbytes, direction, remote_ip="", is_dns=False,
                proto="", service_port=None, new_conn=False):
        minute = int(ts // 60)
        finished = None
        if self.cur_min is None:
            self._reset_cur(minute)
        elif minute != self.cur_min:
            finished = self.finish()
            self._reset_cur(minute)
        c = self.cur
        if direction == "sent":
            c["packets"] += 1
            c["bytes_up"] += nbytes
        else:
            c["bytes_down"] += nbytes
        if remote_ip and len(self.cur_dests) < 5000:
            self.cur_dests.add(remote_ip)
        if is_dns:
            c["dns"] += 1
        if new_conn:
            c["new_conns"] += 1
        if proto and len(self.protocols) < 40:
            self.protocols[proto] += 1
        elif proto in self.protocols:
            self.protocols[proto] += 1
        if service_port and (len(self.services) < 40 or
                             service_port in self.services):
            self.services[service_port] += 1
        return finished

    def finish(self):
        """Close the current minute: returns (values, mean, std, n) BEFORE
        updating, so the caller can compare against the old baseline."""
        if self.cur is None:
            return None
        vals = dict(self.cur)
        vals["destinations"] = len(self.cur_dests)
        snapshot = (vals, dict(self.mean),
                    {f: math.sqrt(max(0.0, self.var[f]))
                     for f in self.FEATURES}, self.n)
        self.n += 1
        a = max(self.ALPHA, 1.0 / self.n)
        for f in self.FEATURES:
            x = vals[f]
            diff = x - self.mean[f]
            self.mean[f] += a * diff
            self.var[f] = (1 - a) * (self.var[f] + a * diff * diff)
        with contextlib.suppress(ValueError, OverflowError, OSError):
            self.hours[time.localtime(self.cur_min * 60).tm_hour] += 1
        self.cur = None
        return snapshot

    def to_dict(self):
        return {"n": self.n, "mean": self.mean, "var": self.var,
                "hours": self.hours,
                "protocols": dict(self.protocols.most_common(20)),
                "services": {str(k): v for k, v in
                             self.services.most_common(20)},
                "countries": sorted(self.countries)[:60]}

    @classmethod
    def from_dict(cls, d):
        b = cls()
        with contextlib.suppress(TypeError, ValueError, AttributeError):
            b.n = int(d.get("n", 0))
            for f in cls.FEATURES:
                b.mean[f] = float((d.get("mean") or {}).get(f, 0.0))
                b.var[f] = float((d.get("var") or {}).get(f, 0.0))
            hrs = d.get("hours") or []
            if len(hrs) == 24:
                b.hours = [int(x) for x in hrs]
            b.protocols = Counter(d.get("protocols") or {})
            b.services = Counter({int(k): v for k, v in
                                  (d.get("services") or {}).items()
                                  if str(k).isdigit()})
            b.countries = set(d.get("countries") or [])
        return b

    def usual_hours_text(self):
        if self.n < 30:
            return "still learning"
        top = sorted(range(24), key=lambda h: -self.hours[h])[:4]
        return ", ".join(f"{h:02d}:00" for h in sorted(top))


class BaselineEngine:
    # minimum absolute values per minute before anything is called unusual
    FLOORS = {"bytes_up": 5 * 1024 * 1024, "bytes_down": 50 * 1024 * 1024,
              "destinations": 40, "new_conns": 80}

    def __init__(self, config):
        self.config = config
        self.devices = {}

    def get(self, key):
        b = self.devices.get(key)
        if b is None:
            b = self.devices[key] = DeviceBaseline()
        return b

    def check(self, snapshot):
        """Return [(feature, value, mean)] that look unusual for this
        device. Requires enough history and a big deviation in BOTH ratio
        and standard deviations, plus an absolute floor."""
        if not snapshot:
            return []
        vals, mean, std, n = snapshot
        need = int(self.config.get("alerts.baseline_min_minutes", 15))
        if n < need:
            return []
        mult = float(self.config.get("alerts.chatty_multiplier", 4))
        out = []
        for f, floor in self.FLOORS.items():
            v, m, s = vals.get(f, 0), mean.get(f, 0.0), std.get(f, 0.0)
            if v >= floor and v > m * mult and v > m + 4 * max(s, 1.0):
                out.append((f, v, m))
        return out

    def reset(self):
        self.devices.clear()

    def to_dict(self):
        return {k: b.to_dict() for k, b in list(self.devices.items())[:500]}

    def load(self, d):
        for k, bd in (d or {}).items():
            if isinstance(bd, dict):
                self.devices[k] = DeviceBaseline.from_dict(bd)


class ScanTracker:
    """Per-device sliding minute of connection attempts, to notice
    scanning-like behaviour (many distinct targets, few replies)."""

    def __init__(self):
        self.attempts = defaultdict(deque)   # dev -> (ts, target, port)
        self.replied = defaultdict(set)      # dev -> {(target, port)}

    def attempt(self, dev_key, ts, target, port):
        dq = self.attempts[dev_key]
        dq.append((ts, target, port))
        while dq and ts - dq[0][0] > 60:
            dq.popleft()
        if len(dq) > 3000:
            dq.popleft()

    def reply(self, dev_key, target, port):
        s = self.replied[dev_key]
        s.add((target, port))
        if len(s) > 5000:
            s.clear()

    def evaluate(self, dev_key, port_threshold, host_threshold):
        dq = self.attempts.get(dev_key)
        if not dq:
            return None
        rep = self.replied.get(dev_key, set())
        per_host = defaultdict(set)
        per_port = defaultdict(set)
        for _ts, tgt, port in dq:
            if (tgt, port) in rep:
                continue
            per_host[tgt].add(port)
            per_port[port].add(tgt)
        if per_host:
            tgt, ports = max(per_host.items(), key=lambda kv: len(kv[1]))
            if len(ports) >= port_threshold:
                return (f"different ports on {tgt}", len(ports))
        if per_port:
            port, hosts = max(per_port.items(), key=lambda kv: len(kv[1]))
            if len(hosts) >= host_threshold:
                return (f"different hosts on port {port}", len(hosts))
        return None

    def forget(self, dev_key):
        self.attempts.pop(dev_key, None)
        self.replied.pop(dev_key, None)


# ============================================================================
#  12b.  Evidence levels, observations and lookup correlation
#
#  Observations are facts with a source, a time and (when it came from a
#  packet) the packet number; they are never edited. Everything a view
#  shows is a CLAIM built from them and carries one of five levels:
#
#     ◉ Observed    seen directly in a packet from this device
#     ◈ Reported    told to us by another system (router, Pi-hole…)
#     ◎ Correlated  two separate observations line up (lookup → connect)
#     ◌ Inferred    a reasonable guess with counter-explanations
#     ?  Unknown    nothing either way — never shown as "no"
# ============================================================================
LV_OBSERVED, LV_REPORTED, LV_CORRELATED, LV_INFERRED, LV_UNKNOWN = \
    "observed", "reported", "correlated", "inferred", "unknown"
LEVEL_GLYPH = {LV_OBSERVED: "◉", LV_REPORTED: "◈", LV_CORRELATED: "◎",
               LV_INFERRED: "◌", LV_UNKNOWN: "?"}
LEVEL_WORD = {LV_OBSERVED: "Observed", LV_REPORTED: "Reported",
              LV_CORRELATED: "Correlated", LV_INFERRED: "Inferred",
              LV_UNKNOWN: "Unknown"}
LEVEL_HELP = {
    LV_OBSERVED: "Seen directly in a packet (you can open that packet).",
    LV_REPORTED: "Reported by another system you connected (for example "
                 "your Pi-hole), not seen by this computer itself.",
    LV_CORRELATED: "Two separate observations line up — for example a "
                   "device looked a name up and connected to the answer "
                   "a moment later.",
    LV_INFERRED: "A reasonable guess. It could be wrong; the reasons are "
                 "listed.",
    LV_UNKNOWN: "Nothing seen either way. Not seeing something does not "
                "mean it didn't happen."}


def level_label(level, word=True):
    g = LEVEL_GLYPH.get(level, "?")
    return f"{g} {LEVEL_WORD.get(level, 'Unknown')}" if word else g


# ---- how a device is tied to a website -----------------------------------
AS_CONNECTED = "connected"                 # SNI / HTTP Host in its own flow
AS_CONNECTED_LOOKUP = "connected-lookup"   # own lookup, then connected
AS_CONNECTED_AMBIG = "connected-ambiguous" # same, IP serves many names
AS_REPORTED = "reported"                   # a connector says it looked up
AS_LOOKUP_ONLY = "lookup-only"             # looked up, no connection seen
AS_INFERRED = "inferred"                   # another device's lookup
ASSOC_RANK = {AS_CONNECTED: 6, AS_CONNECTED_LOOKUP: 5, AS_CONNECTED_AMBIG: 4,
              AS_REPORTED: 3, AS_LOOKUP_ONLY: 2, AS_INFERRED: 1, "": 0}
ASSOC_LEVEL = {AS_CONNECTED: LV_OBSERVED, AS_CONNECTED_LOOKUP: LV_CORRELATED,
               AS_CONNECTED_AMBIG: LV_CORRELATED, AS_REPORTED: LV_REPORTED,
               AS_LOOKUP_ONLY: LV_OBSERVED, AS_INFERRED: LV_INFERRED,
               "": LV_UNKNOWN}
ASSOC_TEXT = {
    AS_CONNECTED: "connected (name seen in the connection)",
    AS_CONNECTED_LOOKUP: "connected (right after looking it up)",
    AS_CONNECTED_AMBIG: "connected to an address shared by many names",
    AS_REPORTED: "looked up (reported by another system)",
    AS_LOOKUP_ONLY: "looked up — no connection seen",
    AS_INFERRED: "possibly (another device's lookup)",
    "": "unknown"}
ASSOC_SHORT = {AS_CONNECTED: "Connected", AS_CONNECTED_LOOKUP: "Connected",
               AS_CONNECTED_AMBIG: "Connected (shared address)",
               AS_REPORTED: "Looked up (reported)",
               AS_LOOKUP_ONLY: "Looked up only", AS_INFERRED: "Possibly",
               "": "—"}


def assoc_label(assoc):
    return f"{LEVEL_GLYPH[ASSOC_LEVEL.get(assoc, LV_UNKNOWN)]} " \
           f"{ASSOC_SHORT.get(assoc, '—')}"


def better_assoc(a, b):
    return a if ASSOC_RANK.get(a, 0) >= ASSOC_RANK.get(b, 0) else b


# ---- observation kinds (integer codes keep the history file small) ---------
OBS_KINDS = ("arp_reply", "arp_probe", "dhcp_request", "dhcp_ack",
             "dns_query", "dns_answer", "tls_sni", "http_host", "flow_start",
             "mdns", "ssdp", "nd", "nbns", "ra", "rogue_ra", "quic_sni",
             "lldp", "service", "name", "probe", "reported")
OBS_KIND_CODES = {k: i + 1 for i, k in enumerate(OBS_KINDS)}
OBS_CODE_KINDS = {v: k for k, v in OBS_KIND_CODES.items()}
OBS_KIND_TEXT = {
    "arp_reply": "answered ARP", "arp_probe": "asked ARP",
    "dhcp_request": "asked DHCP for an address", "dhcp_ack": "got a DHCP "
    "lease", "dns_query": "looked up a name", "dns_answer": "received a DNS "
    "answer", "tls_sni": "named the site in its secure connection",
    "http_host": "named the site in a plain web request",
    "flow_start": "opened a connection", "mdns": "announced itself (mDNS)",
    "ssdp": "announced itself (SSDP)", "nd": "IPv6 neighbour discovery",
    "nbns": "answered a Windows name query", "ra": "announced an IPv6 "
    "router", "rogue_ra": "announced an unexpected IPv6 router",
    "quic_sni": "named the site in a QUIC handshake",
    "lldp": "switch announcement (LLDP/CDP)", "service": "advertised a "
    "service", "name": "name learned", "probe": "answered a health check",
    "reported": "reported by a connected system"}


class LookupCorrelator:
    """Remembers who looked up what (bounded, time-ordered) so a later
    connection can be tied to the name its device just resolved — the
    level is Correlated, never Observed — and so lookups with no
    connection are shown as exactly that."""

    STRONG_WINDOW = 10.0          # lookup → connection within 10 s
    KEEP = 1800.0                 # forget lookups after 30 minutes

    def __init__(self):
        self.by_dev_ip = {}       # (device, ip) -> deque[(ts, domain)]
        self.by_ip = {}           # ip -> deque[(ts, device, domain)]
        self.order = deque()      # (ts, device, ip) for expiry
        self.used = set()         # (device, domain) that led to a connect

    def note_resolution(self, device, domain, ip, ts):
        k = (device, ip)
        dq = self.by_dev_ip.get(k)
        if dq is None:
            dq = self.by_dev_ip[k] = deque(maxlen=8)
        dq.append((ts, domain))
        ipq = self.by_ip.get(ip)
        if ipq is None:
            ipq = self.by_ip[ip] = deque(maxlen=16)
        ipq.append((ts, device, domain))
        self.order.append((ts, device, ip))
        self._expire(ts)

    def match(self, device, ip, ts):
        """→ (domain, kind) for a new connection from `device` to `ip`.
        kind is "own-recent", "own-old", "other" or ""."""
        dq = self.by_dev_ip.get((device, ip)) if device else None
        if dq:
            t, dom = dq[-1]
            if 0 <= ts - t <= self.STRONG_WINDOW:
                self.used.add((device, dom))
                return dom, "own-recent"
            if ts - t <= self.KEEP:
                self.used.add((device, dom))
                return dom, "own-old"
        ipq = self.by_ip.get(ip)
        if ipq:
            t, _dev, dom = ipq[-1]
            if ts - t <= self.KEEP:
                return dom, "other"
        return "", ""

    def _expire(self, now):
        while self.order and now - self.order[0][0] > self.KEEP:
            t, dev, ip = self.order.popleft()
            dq = self.by_dev_ip.get((dev, ip))
            if dq and dq[-1][0] <= t:
                self.by_dev_ip.pop((dev, ip), None)
            ipq = self.by_ip.get(ip)
            if ipq and ipq[-1][0] <= t:
                self.by_ip.pop(ip, None)
        if len(self.order) > 200000:
            for _ in range(20000):
                self.order.popleft()
        if len(self.used) > 100000:
            self.used.clear()


# ============================================================================
#  12c.  Coverage and claims — "what can I actually see from here?"
#
#  The vantage meter watches what share of unicast traffic belongs to OTHER
#  devices. On an ordinary switched network or Wi-Fi this computer mostly
#  sees its own traffic plus broadcasts ("endpoint view"); behind a hub,
#  a mirror/SPAN port or with monitor-mode Wi-Fi it sees much more. Every
#  view uses this to say what it can't know, instead of implying that
#  "not seen" means "didn't happen".
# ============================================================================
VANTAGE_TEXT = {
    "unknown": ("Still measuring", "Not enough traffic yet to tell what "
                "this computer can see."),
    "endpoint": ("This computer's view", "I see this computer's own "
                 "traffic plus broadcasts and announcements from everyone. "
                 "Other devices' private connections go straight to the "
                 "router and are NOT visible here."),
    "partial": ("Partial view", "I see some traffic between other devices "
                "(a hub, a Wi-Fi quirk or a partial mirror), but not all "
                "of it."),
    "mirror": ("Network-wide view", "Most traffic I see is between other "
               "devices — this looks like a mirror/SPAN port or a hub, so "
               "other devices' connections are visible too."),
    "file": ("Imported capture", "This data comes from a file; where it "
             "was captured (and so what it could see) is unknown."),
}


class VantageMeter:
    """Decayed share of unicast frames that involve neither this computer's
    hardware address nor its IP."""

    DECAY = 0.9995

    def __init__(self):
        self.own = 0.0
        self.third = 0.0
        self.frames = 0
        self.bcast = 0

    def note(self, d, my_macs, my_ips):
        self.frames += 1
        if d["multicast"]:
            self.bcast += 1
            return
        sm, dm = d["src_mac"], d["dst_mac"]
        if sm and dm and my_macs:
            mine = sm in my_macs or dm in my_macs
        else:
            mine = d["src_ip"] in my_ips or d["dst_ip"] in my_ips
        self.own *= self.DECAY
        self.third *= self.DECAY
        if mine:
            self.own += 1.0
        else:
            self.third += 1.0

    def share_third(self):
        tot = self.own + self.third
        return self.third / tot if tot else 0.0

    def classify(self, offline=False):
        if offline:
            return "file"
        if self.own + self.third < 150:
            return "unknown"
        r = self.share_third()
        if r < 0.02:
            return "endpoint"
        if r < 0.35:
            return "partial"
        return "mirror"

    def to_dict(self):
        return {"own": self.own, "third": self.third, "frames": self.frames,
                "bcast": self.bcast}

    def load(self, d):
        with contextlib.suppress(TypeError, ValueError, AttributeError):
            self.own = float(d.get("own", 0))
            self.third = float(d.get("third", 0))
            self.frames = int(d.get("frames", 0))
            self.bcast = int(d.get("bcast", 0))


def coverage_rows(model, data_mode="live", active=False):
    """[(question, answer, level, why)] — the coverage card's content."""
    v = model.vantage.classify(offline=data_mode in ("offline", "session"))
    rows = []
    devs = [d for d in model.registry.by_key.values()]
    heard = sum(1 for d in devs if d.packets_out == 0)
    rows.append((
        "Which devices are on the network?",
        f"{len(devs)} found" + (f" ({heard} only heard about, never seen "
                                f"sending)" if heard else ""),
        LV_OBSERVED if devs else LV_UNKNOWN,
        "Devices appear when they send something local (ARP, DHCP, mDNS…)."
        + ("" if active else " In Quiet Mode, silent devices that never "
           "announce themselves can be missed.")))
    if v in ("endpoint", "unknown", "file"):
        rows.append((
            "What do OTHER devices connect to?",
            "Mostly not visible from here" if v == "endpoint" else
            VANTAGE_TEXT[v][0],
            LV_UNKNOWN,
            "Their lookups (if they use plain DNS through this computer) "
            "and broadcasts are visible; their private connections go "
            "straight to the router. A router or Pi-hole connection can "
            "add this."))
    else:
        rows.append(("What do OTHER devices connect to?",
                     "Visible (" + VANTAGE_TEXT[v][0].lower() + ")",
                     LV_OBSERVED, VANTAGE_TEXT[v][1]))
    enc = sum(model.dns.encrypted_seen.values())
    plain = model.dns.queries
    if enc and not plain:
        dns_ans, lvl = "Hidden: lookups are encrypted (DoH/DoT)", \
            LV_UNKNOWN
    elif enc:
        dns_ans, lvl = "Partly hidden: some devices use encrypted DNS", \
            LV_OBSERVED
    else:
        dns_ans, lvl = "Plain DNS lookups are visible", LV_OBSERVED
    rows.append(("Which website names are looked up?", dns_ans, lvl,
                 "Encrypted DNS and VPNs hide names; a lookup alone does "
                 "not prove a visit."))
    if model.vpn.get("iface") or model.vpn.get("endpoint"):
        rows.append(("Internet destinations of this computer",
                     "Hidden inside a VPN tunnel", LV_UNKNOWN,
                     "Only the tunnel endpoint is visible."))
    rows.append(("Full web addresses and page contents",
                 "Never visible for https", LV_UNKNOWN,
                 "Only the site NAME (e.g. example.com) can be seen."))
    return rows


def blind_spots(model, data_mode="live", active=False):
    out = []
    v = model.vantage.classify(offline=data_mode in ("offline", "session"))
    if v == "endpoint":
        out.append("Other devices' connections (switched network)")
    if not active and data_mode == "live":
        out.append("Silent devices (Quiet Mode sends no probes)")
    if model.dns.encrypted_seen:
        out.append("Encrypted DNS lookups")
    if model.vpn.get("iface") or model.vpn.get("endpoint"):
        out.append("Traffic inside the VPN")
    return out


_NAME_SOURCE = {"user": ("you named it", LV_REPORTED),
                "dhcp": ("it announced this name via DHCP", LV_OBSERVED),
                "mdns": ("it announced this name via mDNS", LV_OBSERVED),
                "nbns": ("it answered a Windows name query", LV_OBSERVED),
                "ssdp": ("it announced itself via UPnP", LV_OBSERVED),
                "rdns": ("your DNS server's reverse lookup", LV_REPORTED),
                "vendor": ("guessed from the maker and device type",
                           LV_INFERRED),
                "": ("no name seen", LV_UNKNOWN)}
_EXIST_OBS = ("arp_reply", "dhcp_request", "dhcp_ack", "mdns", "ssdp", "nd",
              "nbns", "ra")


def device_name_source(dev):
    if dev.alias:
        return "user"
    if dev.dhcp_hostname:
        return "dhcp"
    if dev.mdns_name:
        return "mdns"
    if dev.hostname and dev.hostname_source in ("nbns", "rdns", "mdns",
                                                "dhcp"):
        return dev.hostname_source
    if dev.ssdp_name:
        return "ssdp"
    if dev.vendor or dev.device_class != "Unknown":
        return "vendor"
    return ""


def device_claims(model, dev):
    """[(claim, value, level, why, proof_kinds)] for the inspector."""
    claims = []
    if dev.packets_out:
        lvl, why = LV_OBSERVED, "It sent traffic on your local network."
    elif any(e.source in ("arp_reply", "dhcp_lease", "dhcp_client",
                          "ipv6_nd", "mdns", "ssdp", "nbns")
             for e in dev.evidence):
        lvl, why = LV_OBSERVED, "It answered or announced itself."
    else:
        lvl, why = LV_INFERRED, ("Only heard about: other traffic was "
                                 "addressed to it, but it hasn't been seen "
                                 "sending anything itself.")
    claims.append(("Is on your network", dev.confidence + " confidence",
                   lvl, why, _EXIST_OBS))
    src = device_name_source(dev)
    text, lvl = _NAME_SOURCE.get(src, _NAME_SOURCE[""])
    claims.append(("Name", dev.display_name(), lvl, _cap(text) + ".",
                   ("dhcp_request", "dhcp_ack", "mdns", "nbns", "ssdp")))
    if dev.device_class != "Unknown":
        claims.append(("Kind of device",
                       f"{dev.class_confidence} {dev.device_class}".strip(),
                       LV_INFERRED, "; ".join(dev.class_reasons[:3]) or
                       "Combined weak hints.", ()))
    else:
        claims.append(("Kind of device", "Unknown", LV_UNKNOWN,
                       "Not enough clues yet.", ()))
    if dev.ip:
        claims.append(("Address", dev.ip, LV_OBSERVED,
                       "Seen in its own traffic or its DHCP lease.",
                       ("dhcp_ack", "arp_reply")))
    now = model.now()
    if dev.state == STATE_ACTIVE:
        claims.append(("Online", f"yes — seen {human_duration(max(0, now - dev.last_seen))} ago",
                       LV_OBSERVED, "Recent traffic or replies.", ()))
    else:
        claims.append(("Online", f"not seen for "
                                 f"{human_duration(max(0, now - dev.last_seen))}",
                       LV_UNKNOWN, "Not seeing a device doesn't prove it's "
                                   "off — it may just be quiet.", ()))
    conn = look = poss = 0
    for dom in dev.websites:
        w = model.websites.get(dom)
        a = w.ties.get(dev.key, [""])[0] if w else ""
        if ASSOC_RANK.get(a, 0) >= 4:
            conn += 1
        elif a in (AS_LOOKUP_ONLY, AS_REPORTED):
            look += 1
        else:
            poss += 1
    if conn or look or poss:
        claims.append(("Websites", f"{conn} connected · {look} looked up "
                                   f"only · {poss} possibly",
                       LV_OBSERVED if conn else
                       (LV_CORRELATED if look else LV_INFERRED),
                       "Connected = name seen in its connection or right "
                       "after its own lookup.",
                       ("tls_sni", "http_host", "dns_answer")))
    return claims


def device_weakest(model, dev):
    """Three-glyph evidence signature: exists · name · kind."""
    c = device_claims(model, dev)
    return " ".join(LEVEL_GLYPH[x[2]] for x in c[:3])


# ============================================================================
#  13.  NetworkModel — the single analysis core
#
#  Every view (tabs, map, reports, exports, sessions) reads from this one
#  object. It has no Tk dependency, so the self-tests and Demo Mode drive
#  exactly the same logic as live capture. The GUI drains its small event
#  "outboxes" (feed lines, timeline entries, alerts, dirty rows) in batches.
# ============================================================================
