def migrate_config(data):
    """Bring an older settings file up to the current schema without
    losing anything the user chose."""
    ver = int(data.get("config_version", 1) or 1)
    if ver < 2:
        perf = data.setdefault("performance", {})
        if "mode" not in perf:
            perf["mode"] = "Low CPU" if perf.get("cpu_friendly_mode") \
                else "Automatic"
        data["config_version"] = 2
    return data


class AppConfig:
    """JSON-backed settings. Degrades to defaults on any read/parse problem
    rather than crashing (keeping a backup of the damaged file); migrates
    old schemas; never stores credentials."""

    def __init__(self, path=None):
        default_path = os.path.join(SCRIPT_DIR, "miniwireshark_config.json")
        if path is None:
            path = os.environ.get("MINIWIRESHARK_CONFIG")
        if path is None:
            if os.path.exists(default_path) or _dir_writable(SCRIPT_DIR):
                path = default_path
            else:
                path = os.path.join(PATHS.data, "miniwireshark_config.json")
        self.path = path
        self.warning = ""
        self.data = self._load()

    def _load(self):
        defaults = _default_config()
        try:
            if not os.path.exists(self.path):
                return defaults
            with open(self.path, "r", encoding="utf-8") as f:
                data = json.load(f)
            if not isinstance(data, dict):
                raise ValueError("config is not an object")
            data = migrate_config(data)
            merged = _default_config()
            for section, vals in data.items():
                if section in merged and isinstance(vals, dict) and \
                        isinstance(merged[section], dict):
                    merged[section].update(vals)
            merged["config_version"] = CONFIG_SCHEMA_VERSION
            return merged
        except (OSError, ValueError) as e:
            LOG.warning("config unreadable (%s); using defaults", e)
            with contextlib.suppress(OSError):
                shutil.copyfile(self.path, self.path + ".damaged")
            self.warning = ("Your settings file looked damaged, so I reset "
                            "it to defaults (a copy was kept as "
                            "“.damaged”).")
            return defaults

    def get(self, dotted, default=None):
        section, _, key = dotted.partition(".")
        return self.data.get(section, {}).get(key, default)

    def set(self, dotted, value):
        section, _, key = dotted.partition(".")
        self.data.setdefault(section, {})[key] = value

    def save(self):
        try:
            bak = self.path + ".bak"
            if os.path.exists(self.path) and not self.warning:
                try:
                    stale = time.time() - os.path.getmtime(bak) > 86400
                except OSError:
                    stale = True
                if stale:
                    with contextlib.suppress(OSError):
                        shutil.copyfile(self.path, bak)
            atomic_write_json(self.path, self.data)
            return True
        except OSError:
            LOG.warning("could not save settings to %s", self.path)
            return False

    def reset(self, section=None):
        fresh = _default_config()
        if section:
            self.data[section] = fresh.get(section, {})
        else:
            self.data = fresh
        self.save()


def config_defaults_flat():
    out = {}
    for sec, vals in _default_config().items():
        if isinstance(vals, dict):
            for k in vals:
                out[f"{sec}.{k}"] = vals[k]
    return out


class KnownDevicesStore:
    """What YOU told MiniWireshark about your devices (names, notes,
    'mine', 'expected', 'never merge'). Kept locally in the data folder so
    it survives restarts, independently of the optional history mode."""

    def __init__(self, path):
        self.path = path
        self.data = read_json(path, {}) or {}
        if not isinstance(self.data, dict):
            self.data = {}

    def get(self, key):
        return self.data.get(key)

    def update_from(self, dev):
        entry = {"alias": dev.alias, "notes": dev.notes, "mine": dev.mine,
                 "expected": dev.expected, "pinned": dev.pinned_no_merge,
                 "never_merge": sorted(dev.never_merge),
                 "vendor": dev.vendor, "last_ip": dev.ip,
                 "updated": time.time()}
        if not any((dev.alias, dev.notes, dev.mine, dev.expected,
                    dev.pinned_no_merge, dev.never_merge)):
            self.data.pop(dev.key, None)
        else:
            self.data[dev.key] = entry
        self.save()

    def forget(self, key):
        if self.data.pop(key, None) is not None:
            self.save()

    def save(self):
        try:
            atomic_write_json(self.path, self.data)
        except OSError:
            LOG.warning("could not save known devices")


class SessionCodec:
    """Session file format v2 (.mwsession.json). Old v1 files (3.0's
    predecessor) still load; missing fields simply take defaults."""

    @staticmethod
    def serialize(model, meta=None):
        meta = dict(meta or {})
        now = model.now()
        flows = sorted(model.flows.all_flows(), key=lambda f: -f.total_bytes)
        payload = {
            "schema_version": SESSION_SCHEMA_VERSION,
            "app": {"name": APP_NAME, "version": SCRIPT_VERSION},
            "exported_at": time.time(),
            "packet_count": model.count,
            "session": {
                "started": meta.get("started") or model.metrics.first_ts,
                "ended": model.metrics.last_ts or now,
                "data_source": meta.get("data_source", "live"),
                "interface": meta.get("interface", ""),
                "gateway": model.gateway_ip,
                "my_ips": sorted(model.my_ips),
                "demo": bool(model.demo),
                "vpn": dict(model.vpn),
            },
            "devices": [device_to_dict(d) for d in
                        model.registry.by_key.values()],
            "websites": [website_to_dict(w) for w in model.websites.values()],
            "remote_hosts": [remote_to_dict(r) for r in
                             sorted(model.remote_hosts.values(),
                                    key=lambda r: -r.bytes_total)[:5000]],
            "flows_summary": [f.to_dict() for f in flows[:2000]],
            "alerts": [alert_to_dict(model.alerts.alerts[aid])
                       for aid in model.alerts.order
                       if aid in model.alerts.alerts],
            "timeline": [{k: v for k, v in e.items()
                          if k in ("when", "kind", "severity", "text",
                                   "ref", "device")}
                         for e in list(model.timeline)[-2000:]],
            "metrics": model.metrics.to_dict(),
            "dns": model.dns.to_dict(),
            "baselines": model.baselines.to_dict(),
            "dhcp_servers": dict(model.dhcp_servers),
            "doh_seen": {k: sorted(v) for k, v in model.doh_seen.items()},
            "health": {k: v for k, v in model.health.items()
                       if isinstance(v, (str, int, float, bool, type(None)))},
            "observations": [list(o) for o in list(model.obs_recent)[-3000:]],
            "bindings": model.registry.bindings.to_list(3000),
            "aliases": dict(list(model.registry.alias.items())[-2000:]),
            "corrections": model.journal.to_list(),
            "network_id": getattr(model, "network_id", ""),
        }
        return payload

    @staticmethod
    def migrate(payload):
        if not isinstance(payload, dict):
            raise ValueError("not a MiniWireshark session (no object)")
        ver = int(payload.get("schema_version", 1) or 1)
        if ver > SESSION_SCHEMA_VERSION:
            LOG.info("session from a newer version (%s); loading what we "
                     "understand", ver)
        if ver < 2:
            # v1: devices[].hostname was the display name; nothing else
            for dd in payload.get("devices", []) or []:
                if isinstance(dd, dict) and "hostname_display" not in dd:
                    dd["hostname_display"] = dd.get("hostname", "")
            payload["schema_version"] = 2
        if ver < 3:
            # v3 adds site ties, connection association levels and the
            # recent observations; older files simply have none
            payload["schema_version"] = 3
        if not any(k in payload for k in ("devices", "websites",
                                          "remote_hosts", "alerts")):
            raise ValueError("this file has no devices, websites, remote "
                             "hosts or alerts")
        return payload

    @staticmethod
    def load(payload, model):
        """Populate an EMPTY model from a payload. Everything loaded is
        marked live=False so it can never be mistaken for live data."""
        payload = SessionCodec.migrate(payload)
        sess = payload.get("session") or {}
        model.use_packet_clock = True
        model.offline_now = float(sess.get("ended") or
                                  payload.get("exported_at") or time.time())
        model.set_identity(gateway_ip=sess.get("gateway", "") or "",
                           my_ips=sess.get("my_ips") or [])
        model.demo = bool(sess.get("demo"))
        for dd in payload.get("devices", []) or []:
            if not isinstance(dd, dict):
                continue
            dev = device_from_dict(dd)
            dev.live = False
            if dev.state not in (STATE_ACTIVE, STATE_IDLE, STATE_INACTIVE,
                                 STATE_EXPIRED):
                dev.state = STATE_EXPIRED
            model.registry.by_key[dev.key] = dev
            for ip in dev.ipv4s | dev.ipv6 | ({dev.ip} if dev.ip else set()):
                model.registry.ip_to_key[ip] = dev.key
            if dev.device_class == "Unknown":
                model._classify_dirty.add(dev.key)
        for wd in payload.get("websites", []) or []:
            if isinstance(wd, dict) and wd.get("domain"):
                rec = website_from_dict(wd)
                rec.live = False
                model.websites[rec.domain] = rec
        for rd in payload.get("remote_hosts", []) or []:
            if isinstance(rd, dict) and rd.get("ip"):
                rec = remote_from_dict(rd)
                rec.live = False
                model.remote_hosts[rec.ip] = rec
        for fd in payload.get("flows_summary", []) or []:
            if isinstance(fd, dict):
                f = FlowRecord.from_dict(fd)
                f.fid = model.flows.next_id
                model.flows.next_id += 1
                model.flows.archive.append(f)
                model.flows.by_id[f.fid] = f
        for ad in payload.get("alerts", []) or []:
            if isinstance(ad, dict):
                a = alert_from_dict(ad)
                model.alerts.alerts[a.id] = a
                model.alerts.order.append(a.id)
        for e in payload.get("timeline", []) or []:
            if isinstance(e, dict) and "text" in e:
                ref = e.get("ref")
                model.timeline.append({
                    "when": float(e.get("when") or 0), "kind": e.get("kind",
                                                                    ""),
                    "severity": e.get("severity", "INFO"),
                    "text": sanitize_text(e.get("text", ""), 400),
                    "ref": tuple(ref) if isinstance(ref, list) else ref,
                    "device": e.get("device", ""), "live": False})
        model.metrics.load(payload.get("metrics") or {})
        model.dns.load(payload.get("dns") or {})
        model.baselines.load(payload.get("baselines") or {})
        for k, v in (payload.get("dhcp_servers") or {}).items():
            with contextlib.suppress(TypeError, ValueError):
                model.dhcp_servers[k] = int(v)
        for k, v in (payload.get("doh_seen") or {}).items():
            model.doh_seen[k] = set(v or [])
        model.count = int(payload.get("packet_count", 0) or 0)
        vpn = sess.get("vpn")
        if isinstance(vpn, dict):
            model.vpn.update(vpn)
        with contextlib.suppress(TypeError, ValueError, IndexError):
            model.registry.bindings.load(payload.get("bindings"))
        al = payload.get("aliases")
        if isinstance(al, dict):
            model.registry.alias.update(
                {sanitize_text(k, 80): sanitize_text(v, 80)
                 for k, v in list(al.items())[:5000]
                 if isinstance(k, str) and isinstance(v, str)})
        model.network_id = sanitize_text(payload.get("network_id", ""), 32)
        for o in (payload.get("observations") or [])[-3000:]:
            if isinstance(o, list) and len(o) == 6 and \
                    o[2] in OBS_KIND_CODES and isinstance(o[4], dict):
                with contextlib.suppress(TypeError, ValueError):
                    model.observe(o[2], sanitize_text(o[3], 120), float(o[1]),
                                  o[4], o[5] if isinstance(o[5], int)
                                  else None)
        model._classify()
        return payload


# ---- optional local history (SQLite) ----------------------------------------
HISTORY_RETENTION = {"Session only": 0, "7 days": 7, "30 days": 30,
                     "90 days": 90, "Custom": None}
STORE_SCHEMA_VERSION = 3

# Numbered migrations. Each runs inside one transaction; a crash rolls it
# back and the next start retries. The file is copied to .vN.bak first.
STORE_MIGRATIONS = {
    1: """
    CREATE TABLE IF NOT EXISTS meta(k TEXT PRIMARY KEY, v TEXT);
    CREATE TABLE IF NOT EXISTS devices(key TEXT PRIMARY KEY, data TEXT,
        first_seen REAL, last_seen REAL);
    CREATE TABLE IF NOT EXISTS presence(device_key TEXT, start REAL,
        end REAL, PRIMARY KEY(device_key, start));
    CREATE TABLE IF NOT EXISTS traffic(device_key TEXT, day TEXT,
        bytes_up INTEGER, bytes_down INTEGER, packets INTEGER,
        PRIMARY KEY(device_key, day));
    CREATE TABLE IF NOT EXISTS alerts(id TEXT PRIMARY KEY, kind TEXT,
        severity TEXT, device_key TEXT, reason TEXT, at REAL);
    CREATE TABLE IF NOT EXISTS domains(domain TEXT, day TEXT,
        requests INTEGER, bytes INTEGER, PRIMARY KEY(domain, day));
    CREATE TABLE IF NOT EXISTS baselines(device_key TEXT PRIMARY KEY,
        data TEXT, updated REAL);
    """,
    2: """
    CREATE TABLE IF NOT EXISTS migration_log(version INTEGER, phase TEXT,
        at REAL);
    CREATE TABLE IF NOT EXISTS sessions(id INTEGER PRIMARY KEY,
        started REAL, ended REAL, source TEXT, iface TEXT, network TEXT,
        app_version TEXT);
    CREATE TABLE IF NOT EXISTS observations(ts REAL, session INTEGER,
        kind INTEGER, subject TEXT, data TEXT, pkt INTEGER);
    CREATE INDEX IF NOT EXISTS obs_subject ON observations(subject, ts);
    CREATE INDEX IF NOT EXISTS obs_kind ON observations(kind, ts);
    CREATE TABLE IF NOT EXISTS resolutions(ts REAL, session INTEGER,
        device TEXT, domain TEXT, ip TEXT);
    CREATE INDEX IF NOT EXISTS res_ip ON resolutions(ip, ts);
    CREATE INDEX IF NOT EXISTS res_domain ON resolutions(domain, ts);
    CREATE TABLE IF NOT EXISTS flows(session INTEGER, fid INTEGER,
        start REAL, end REAL, device TEXT, remote TEXT, port INTEGER,
        transport TEXT, app TEXT, domain TEXT, assoc TEXT,
        bytes_out INTEGER, bytes_in INTEGER, packets INTEGER,
        PRIMARY KEY(session, fid));
    CREATE INDEX IF NOT EXISTS flows_device ON flows(device, start);
    CREATE INDEX IF NOT EXISTS flows_remote ON flows(remote, start);
    CREATE TABLE IF NOT EXISTS site_ties(session INTEGER, device TEXT,
        domain TEXT, assoc TEXT, first REAL, last REAL, n INTEGER,
        PRIMARY KEY(session, device, domain));
    CREATE INDEX IF NOT EXISTS ties_domain ON site_ties(domain, last);
    """,
    3: """
    CREATE TABLE IF NOT EXISTS events(ts REAL, session INTEGER, kind TEXT,
        severity TEXT, text TEXT, ref_kind TEXT, ref_id TEXT,
        device TEXT);
    CREATE INDEX IF NOT EXISTS events_ts ON events(ts);
    CREATE INDEX IF NOT EXISTS events_kind ON events(kind, ts);
    CREATE INDEX IF NOT EXISTS events_device ON events(device, ts);
    CREATE TABLE IF NOT EXISTS packet_segments(session INTEGER,
        first_no INTEGER, last_no INTEGER, t0 REAL, t1 REAL, path TEXT,
        bytes INTEGER, linktype INTEGER,
        PRIMARY KEY(session, first_no));
    """,
}


class Store:
    """Durable, optional history in one SQLite file (WAL mode).

    • One writer thread owns the only write connection; callers hand over
      small batches (observations, lookups, connections, site ties,
      timeline events) about once a second.
    • Readers open their own read-only connections, so a history query
      never blocks capture or the writer.
    • Numbered migrations with a .vN.bak copy first; a nightly .bak copy;
      integrity check at open with automatic recovery from the backup.
    • No packet payloads are ever stored here (the optional packet ring
      keeps raw packets in separate files, off by default)."""

    def __init__(self, path, session_id=None, meta=None):
        self.path = path
        self.session = session_id if session_id is not None else \
            int(time.time())
        self.meta = dict(meta or {})
        self.q = queue.Queue(maxsize=400)
        self.error = ""
        self.recovered = ""
        self.written = Counter()
        self.dropped_batches = 0
        self._stop = False
        self._ready = threading.Event()
        self._idle = threading.Event()
        self._idle.set()
        self._thread = threading.Thread(target=self._run, daemon=True,
                                        name="history-writer")
        self._thread.start()
        self._ready.wait(10)

    # ---- opening, migrations, recovery ---------------------------------------
    def _check_integrity(self):
        if not os.path.exists(self.path):
            return
        bad = ""
        try:
            con = sqlite3.connect(self.path, timeout=10)
            row = con.execute("PRAGMA quick_check").fetchone()
            con.close()
            if not row or row[0] != "ok":
                bad = str(row[0] if row else "no answer")
        except sqlite3.DatabaseError as e:
            bad = str(e)
        if not bad:
            return
        aside = f"{self.path}.corrupt-{int(time.time())}"
        with contextlib.suppress(OSError):
            os.replace(self.path, aside)
        for suffix in ("-wal", "-shm"):
            with contextlib.suppress(OSError):
                os.remove(self.path + suffix)
        bak = self.path + ".bak"
        if os.path.exists(bak):
            with contextlib.suppress(OSError):
                shutil.copyfile(bak, self.path)
            self.recovered = (f"The history file was damaged ({bad}); it was "
                              f"set aside and last night's backup was "
                              f"restored.")
        else:
            self.recovered = (f"The history file was damaged ({bad}); it was "
                              f"set aside and a new one was started.")
        LOG.warning("history: %s", self.recovered)

    def _connect(self):
        self._check_integrity()
        con = sqlite3.connect(self.path, timeout=15)
        with contextlib.suppress(sqlite3.Error):
            con.execute("PRAGMA journal_mode=WAL")
            con.execute("PRAGMA synchronous=NORMAL")
        con.execute("CREATE TABLE IF NOT EXISTS meta(k TEXT PRIMARY KEY, "
                    "v TEXT)")
        row = con.execute("SELECT v FROM meta WHERE k='schema'").fetchone()
        ver = int(row[0]) if row and str(row[0]).isdigit() else 0
        if ver < STORE_SCHEMA_VERSION and ver > 0:
            with contextlib.suppress(OSError):
                con.commit()
                shutil.copyfile(self.path, f"{self.path}.v{ver}.bak")
        for v in range(ver + 1, STORE_SCHEMA_VERSION + 1):
            self._migrate(con, v)
        con.execute("INSERT OR REPLACE INTO sessions VALUES(?,?,?,?,?,?,?)",
                    (self.session, time.time(), None,
                     self.meta.get("source", ""), self.meta.get("iface", ""),
                     self.meta.get("network", ""), SCRIPT_VERSION))
        con.commit()
        return con

    @staticmethod
    def _migrate(con, version):
        con.commit()
        old_level = con.isolation_level
        con.isolation_level = None            # explicit transaction below
        try:
            con.execute("BEGIN")
            if version >= 2:
                con.execute("CREATE TABLE IF NOT EXISTS migration_log("
                            "version INTEGER, phase TEXT, at REAL)")
                con.execute("INSERT INTO migration_log VALUES(?,?,?)",
                            (version, "start", time.time()))
            for stmt in STORE_MIGRATIONS[version].split(";"):
                if stmt.strip():
                    con.execute(stmt)
            con.execute("INSERT OR REPLACE INTO meta VALUES('schema', ?)",
                        (str(version),))
            if version >= 2:
                con.execute("INSERT INTO migration_log VALUES(?,?,?)",
                            (version, "done", time.time()))
            con.execute("COMMIT")
        except sqlite3.Error:
            with contextlib.suppress(sqlite3.Error):
                con.execute("ROLLBACK")
            raise
        finally:
            con.isolation_level = old_level

    def _backup_if_due(self, con):
        bak = self.path + ".bak"
        try:
            age = time.time() - os.path.getmtime(bak)
        except OSError:
            age = 1e9
        if age < 20 * 3600:
            return
        try:
            dst = sqlite3.connect(bak + ".tmp")
            con.backup(dst)
            dst.close()
            os.replace(bak + ".tmp", bak)
        except (sqlite3.Error, OSError) as e:
            LOG.info("history backup skipped: %s", e)

    # ---- writer thread -------------------------------------------------------------
    def _run(self):
        try:
            con = self._connect()
        except sqlite3.Error as e:
            self.error = str(e)
            LOG.warning("history db unavailable: %s", e)
            self._ready.set()
            return
        self._ready.set()
        self._backup_if_due(con)
        last_backup_check = time.time()
        while True:
            try:
                job = self.q.get(timeout=1.0)
            except queue.Empty:
                self._idle.set()
                if self._stop:
                    break
                if time.time() - last_backup_check > 3600:
                    last_backup_check = time.time()
                    self._backup_if_due(con)
                continue
            if job is None:
                break
            self._idle.clear()
            for attempt in range(3):
                try:
                    job(con)
                    con.commit()
                    break
                except sqlite3.OperationalError as e:
                    self.error = str(e)
                    with contextlib.suppress(sqlite3.Error):
                        con.rollback()
                    if "locked" not in str(e) or attempt == 2:
                        LOG.warning("history write failed: %s", e)
                        break
                    time.sleep(0.2 * (attempt + 1))
                except sqlite3.Error as e:
                    self.error = str(e)
                    with contextlib.suppress(sqlite3.Error):
                        con.rollback()
                    LOG.warning("history write failed: %s", e)
                    break
            if self.q.empty():
                self._idle.set()
        with contextlib.suppress(sqlite3.Error):
            con.execute("UPDATE sessions SET ended=? WHERE id=?",
                        (time.time(), self.session))
            con.commit()
            con.close()
        self._idle.set()

    def submit(self, job):
        if self.error and not self._thread.is_alive():
            return False
        try:
            self._idle.clear()
            self.q.put_nowait(job)
            return True
        except queue.Full:
            self.dropped_batches += 1
            if self.q.empty():
                self._idle.set()
            return False

    def flush_now(self, timeout=5.0):
        """Wait until everything handed over so far is on disk."""
        t_end = time.time() + timeout
        while time.time() < t_end:
            if not self.q.empty():
                time.sleep(0.02)        # never spin: it starves the writer
                continue
            if self._idle.wait(0.05) and self.q.empty():
                return True
        return False

    def stop(self, wait=0.0):
        self._stop = True
        with contextlib.suppress(queue.Full):
            self.q.put_nowait(None)
        if wait:
            self._thread.join(wait)

    # ---- batched writes ------------------------------------------------------------
    def write_observations(self, obs):
        if not obs:
            return True
        sess = self.session
        rows = [(o[1], sess, OBS_KIND_CODES.get(o[2], 0), o[3],
                 json.dumps(o[4], separators=(",", ":"), default=str)
                 if o[4] else "", o[5]) for o in obs]

        def job(con):
            con.executemany("INSERT INTO observations VALUES(?,?,?,?,?,?)",
                            rows)
            self.written["observations"] += len(rows)
        return self.submit(job)

    def write_resolutions(self, res):
        if not res:
            return True
        sess = self.session
        rows = [(ts, sess, dev, dom, ip) for ts, dev, dom, ip in res]

        def job(con):
            con.executemany("INSERT INTO resolutions VALUES(?,?,?,?,?)",
                            rows)
            self.written["resolutions"] += len(rows)
        return self.submit(job)

    def write_flows(self, flows):
        if not flows:
            return True
        sess = self.session
        rows = [(sess, f.fid, f.first_seen, f.last_seen, f.device_key,
                 f.remote_ip, f.remote_port or 0, f.transport, f.app,
                 f.domain, f.assoc, f.bytes_out, f.bytes_in, f.packets)
                for f in flows]

        def job(con):
            con.executemany("INSERT OR REPLACE INTO flows VALUES"
                            "(?,?,?,?,?,?,?,?,?,?,?,?,?,?)", rows)
            self.written["flows"] += len(rows)
        return self.submit(job)

    def write_site_ties(self, ties):
        """ties: iterable of (device, domain, [assoc, first, last, n])."""
        sess = self.session
        rows = [(sess, dev, dom, t[0], t[1], t[2], t[3])
                for dev, dom, t in ties]
        if not rows:
            return True

        def job(con):
            con.executemany("INSERT OR REPLACE INTO site_ties VALUES"
                            "(?,?,?,?,?,?,?)", rows)
            self.written["site_ties"] += len(rows)
        return self.submit(job)

    def write_events(self, events):
        if not events:
            return True
        sess = self.session
        rows = []
        for e in events:
            ref = e.get("ref") or (None, None)
            if not isinstance(ref, (list, tuple)) or len(ref) != 2:
                ref = (None, None)
            rows.append((e["when"], sess, e.get("kind", ""),
                         e.get("severity", "INFO"), e.get("text", ""),
                         ref[0], None if ref[1] is None else str(ref[1]),
                         e.get("device", "")))

        def job(con):
            con.executemany("INSERT INTO events VALUES(?,?,?,?,?,?,?,?)",
                            rows)
            self.written["events"] += len(rows)
        return self.submit(job)

    def set_session_meta(self, **meta):
        cols = {k: v for k, v in meta.items()
                if k in ("source", "iface", "network")}
        if not cols:
            return True
        sess = self.session

        def job(con):
            for k, v in cols.items():
                con.execute(f"UPDATE sessions SET {k}=? WHERE id=?",
                            (str(v), sess))
        return self.submit(job)

    def write_segment(self, first_no, last_no, t0, t1, path, nbytes, lt):
        sess = self.session

        def job(con):
            con.execute("INSERT OR REPLACE INTO packet_segments VALUES"
                        "(?,?,?,?,?,?,?,?)", (sess, first_no, last_no, t0,
                                              t1, path, nbytes, lt))
        return self.submit(job)

    def write_snapshot(self, snap):
        """3.0-compatible summary snapshot (devices, alerts, domains…)."""
        def job(con):
            day = time.strftime("%Y-%m-%d")
            for key, data, fs, ls, presence, tr in snap["devices"]:
                con.execute("INSERT OR REPLACE INTO devices VALUES(?,?,?,?)",
                            (key, json.dumps(data, default=str), fs, ls))
                for start, end in presence:
                    con.execute("INSERT OR REPLACE INTO presence "
                                "VALUES(?,?,?)", (key, start, end))
                con.execute("INSERT OR REPLACE INTO traffic "
                            "VALUES(?,?,?,?,?)", (key, day) + tuple(tr))
            for a in snap["alerts"]:
                con.execute("INSERT OR IGNORE INTO alerts VALUES(?,?,?,?,?,?)",
                            a)
            for dom, req, b in snap["domains"]:
                con.execute("INSERT OR REPLACE INTO domains "
                            "VALUES(?,?,?,?)", (dom, day, req, b))
            for key, data in snap["baselines"]:
                con.execute("INSERT OR REPLACE INTO baselines VALUES(?,?,?)",
                            (key, json.dumps(data), time.time()))
        return self.submit(job)

    def prune(self, days):
        if not days:
            return False
        cutoff = time.time() - days * 86400
        cday = time.strftime("%Y-%m-%d", time.localtime(cutoff))

        def job(con):
            con.execute("DELETE FROM presence WHERE start < ?", (cutoff,))
            con.execute("DELETE FROM alerts WHERE at < ?", (cutoff,))
            con.execute("DELETE FROM traffic WHERE day < ?", (cday,))
            con.execute("DELETE FROM domains WHERE day < ?", (cday,))
            con.execute("DELETE FROM devices WHERE last_seen < ?", (cutoff,))
            for t, col in (("observations", "ts"), ("resolutions", "ts"),
                           ("flows", "end"), ("site_ties", "last"),
                           ("events", "ts")):
                con.execute(f"DELETE FROM {t} WHERE {col} < ?", (cutoff,))
            con.execute("DELETE FROM sessions WHERE ended IS NOT NULL AND "
                        "ended < ?", (cutoff,))
        return self.submit(job)

    def clear(self, device_key=None):
        def job(con):
            if device_key:
                for t, col in (("devices", "key"), ("presence", "device_key"),
                               ("traffic", "device_key"),
                               ("alerts", "device_key"),
                               ("baselines", "device_key"),
                               ("observations", "subject"),
                               ("resolutions", "device"),
                               ("flows", "device"), ("site_ties", "device"),
                               ("events", "device")):
                    con.execute(f"DELETE FROM {t} WHERE {col}=?",
                                (device_key,))
            else:
                for t in ("devices", "presence", "traffic", "alerts",
                          "domains", "baselines", "observations",
                          "resolutions", "flows", "site_ties", "events",
                          "packet_segments"):
                    con.execute(f"DELETE FROM {t}")
                con.commit()
                con.execute("VACUUM")
        return self.submit(job)

    # ---- reads (own read-only connection each time) ------------------------
    def _reader(self):
        uri = "file:" + urllib.request.pathname2url(
            os.path.abspath(self.path)) + "?mode=ro"
        con = sqlite3.connect(uri, uri=True, timeout=5)
        con.execute("PRAGMA query_only=ON")
        return con

    def query(self, sql, args=(), limit=None):
        """Read-only query. Returns rows, or [] if the file can't be read
        (the error is kept in .error)."""
        if not sql.lstrip().upper().startswith(("SELECT", "WITH")):
            raise ValueError("read-only queries only")
        try:
            con = self._reader()
            try:
                cur = con.execute(sql, args)
                return cur.fetchmany(limit) if limit else cur.fetchall()
            finally:
                con.close()
        except sqlite3.Error as e:
            self.error = str(e)
            return []

    def observations(self, subject, limit=200, since=0.0):
        rows = self.query("SELECT ts, kind, data, pkt, session FROM "
                          "observations WHERE subject=? AND ts>=? ORDER BY "
                          "ts DESC LIMIT ?", (subject, since, limit))
        out = []
        for ts, kind, data, pkt, sess in rows:
            try:
                d = json.loads(data) if data else {}
            except ValueError:
                d = {}
            out.append((ts, OBS_CODE_KINDS.get(kind, "?"), d, pkt, sess))
        return out

    def counts(self):
        out = {}
        for t in ("observations", "resolutions", "flows", "site_ties",
                  "events", "sessions", "devices"):
            r = self.query(f"SELECT COUNT(*) FROM {t}")
            out[t] = r[0][0] if r else 0
        return out

    def schema_version(self):
        r = self.query("SELECT v FROM meta WHERE k='schema'")
        return int(r[0][0]) if r and str(r[0][0]).isdigit() else 0

    def load_baselines(self):
        out = {}
        for key, data in self.query("SELECT device_key, data FROM "
                                    "baselines"):
            with contextlib.suppress(ValueError):
                out[key] = json.loads(data)
        return out

    def known_device_rows(self, limit=500):
        rows = []
        for key, data, fs, ls in self.query(
                "SELECT key, data, first_seen, last_seen FROM devices "
                "ORDER BY last_seen DESC LIMIT ?", (limit,)):
            with contextlib.suppress(ValueError):
                rows.append((key, json.loads(data), fs, ls))
        return rows

    def size_bytes(self):
        total = 0
        for suffix in ("", "-wal", "-journal"):
            with contextlib.suppress(OSError):
                total += os.path.getsize(self.path + suffix)
        return total


HistoryStore = Store          # 3.0 name


def bench_store(n=100000):
    tmp = tempfile.mkdtemp()
    st = Store(os.path.join(tmp, "b.sqlite3"))
    obs = [(i, 1700000000.0 + i * 0.01, "dns_answer", f"dev{i % 50}",
            {"domain": f"d{i % 900}.example", "ip": "93.184.215.14"}, i)
           for i in range(n)]
    t0 = time.perf_counter()
    for k in range(0, n, 5000):
        while not st.write_observations(obs[k:k + 5000]):
            time.sleep(0.01)
    st.flush_now(60)
    dt = time.perf_counter() - t0
    size = st.size_bytes()
    st.stop(5)
    shutil.rmtree(tmp, ignore_errors=True)
    return {"store_obs_per_s": n / dt, "store_bytes_per_obs": size / n}


# ============================================================================
#  14c.  History views — what changed, sessions, packet history
# ============================================================================
CHANGE_PERIODS = {"Last hour": 3600, "Last 24 hours": 86400,
                  "Last 7 days": 7 * 86400, "Since this session started":
                  None}


def change_digest(model, store=None, since=0.0, until=None):
    """What changed between `since` and `until`: new / returning / gone
    devices, first-seen websites, address and DNS changes, network events
    and warnings. In-memory data first; older periods come from the
    history store (if enabled)."""
    until = until or model.now()
    reg = model.registry
    own = set(model.my_ips) | {model.gateway_ip}
    out = {"since": since, "until": until, "new_devices": [],
           "returned": [], "left": [], "new_sites": [], "ip_changes": [],
           "dns_changes": [], "network": [], "alerts": [], "from_store": 0}
    for d in reg.by_key.values():
        if not d.live or not (since <= d.first_seen <= until):
            continue
        if d.ip in own or (d.mac and d.mac in model.my_macs):
            continue
        out["new_devices"].append((d.first_seen, d.key, d.display_name()))
    first_by_root = {}
    for w in model.websites.values():
        r = w.registrable or w.domain
        if r not in first_by_root or w.first_seen < first_by_root[r][0]:
            first_by_root[r] = (w.first_seen, w)
    for r, (fs, w) in first_by_root.items():
        if since <= fs <= until and w.live:
            out["new_sites"].append((fs, r, sorted(w.devices)[:3],
                                     w.best_assoc))
    kinds = {"device back": "returned", "device left": "left",
             "ip changed": "ip_changes", "dns change": "dns_changes",
             "network": "network", "interface": "network",
             "rogue router": "network", "internet": "network"}
    for e in model.timeline:
        k = kinds.get(e.get("kind"))
        if k and since <= e["when"] <= until:
            out[k].append((e["when"], e.get("device", ""), e["text"]))
    for a in model.alerts.alerts.values():
        if a.severity in ("WARNING", "DANGER") and \
                since <= a.first_seen <= until:
            out["alerts"].append((a.first_seen, a.severity, a.reason))
    if store is not None:
        known_new = {k for _t, k, _n in out["new_devices"]}
        rows = store.query(
            "SELECT ts, kind, severity, text, device FROM events WHERE "
            "ts>=? AND ts<=? AND session<>? ORDER BY ts LIMIT 5000",
            (since, until, getattr(store, "session", -1)))
        out["from_store"] = len(rows)
        for ts, kind, sev, text, dev in rows:
            k = kinds.get(kind)
            if kind == "new device" and dev not in known_new:
                out["new_devices"].append((ts, dev, text))
                known_new.add(dev)
            elif kind == "website":
                out["new_sites"].append((ts, text.replace(
                    "First visit to ", ""), [dev] if dev else [], ""))
            elif k:
                out[k].append((ts, dev, text))
            elif kind == "alert" and sev in ("WARNING", "DANGER"):
                out["alerts"].append((ts, sev, text))
    for k in ("new_devices", "returned", "left", "new_sites", "ip_changes",
              "dns_changes", "network", "alerts"):
        out[k].sort(key=lambda t: t[0])
    return out


def timeline_match(e, since=0.0, severity="All", category="All types",
                   device=None, q=""):
    """The in-memory Timeline filter (timeline_sql is its SQL twin)."""
    if e["when"] < since:
        return False
    if severity and severity != "All" and severity != e["severity"]:
        return False
    if category and category != "All types" and \
            TIMELINE_CATEGORY.get(e["kind"], "Devices") != category:
        return False
    if device and e.get("device") != device:
        return False
    q = (q or "").strip().lower()
    if q:
        q = q.replace("%", "").replace("_", "")
        if q not in e["text"].lower() and q not in e["kind"].lower():
            return False
    return True


def timeline_sql(category="All types", severity="All", device=None, q="",
                 since=0.0, until=None, before=None, limit=200,
                 session=None):
    """The Timeline's filters compiled to one read-only SQL query over the
    events table (same meaning as the in-memory filter)."""
    where, args = ["ts >= ?"], [since]
    if until is not None:
        where.append("ts <= ?")
        args.append(until)
    if isinstance(before, (tuple, list)):
        # keyset paging: (ts, rowid) of the last row of the previous page,
        # so events sharing a timestamp are never skipped
        where.append("(ts < ? OR (ts = ? AND rowid < ?))")
        args += [before[0], before[0], before[1]]
    elif before is not None:
        where.append("ts < ?")
        args.append(before)
    if severity and severity != "All":
        where.append("severity = ?")
        args.append(severity)
    if category and category != "All types":
        kinds = [k for k, c in TIMELINE_CATEGORY.items() if c == category]
        if category == "Devices":
            # anything not explicitly categorised counts as a device event
            other = [k for k in TIMELINE_CATEGORY]
            where.append("(kind IN (%s) OR kind NOT IN (%s))" % (
                ",".join("?" * len(kinds)), ",".join("?" * len(other))))
            args += kinds + other
        else:
            where.append("kind IN (%s)" % ",".join("?" * len(kinds)))
            args += kinds
    if device:
        where.append("device = ?")
        args.append(device)
    if q:
        where.append("(LOWER(text) LIKE ? OR LOWER(kind) LIKE ?)")
        like = "%" + q.lower().replace("%", "").replace("_", "") + "%"
        args += [like, like]
    if session is not None:
        where.append("session = ?")
        args.append(session)
    sql = ("SELECT ts, kind, severity, text, ref_kind, ref_id, device, "
           "session, rowid FROM events WHERE " + " AND ".join(where) +
           " ORDER BY ts DESC, rowid DESC LIMIT ?")
    args.append(int(limit))
    return sql, args


def store_events_page(store, before=None, limit=200, **filters):
    """One page of timeline events (newest first) as timeline dicts."""
    sql, args = timeline_sql(before=before, limit=limit, **filters)
    out = []
    for ts, kind, sev, text, rk, rid, dev, sess, rowid in \
            store.query(sql, args):
        ref = (rk, rid) if rk else None
        if ref and rk == "flow":
            with contextlib.suppress(TypeError, ValueError):
                ref = (rk, int(rid))
        out.append({"when": ts, "kind": kind, "severity": sev,
                    "text": text, "ref": ref, "device": dev or "",
                    "session": sess, "live": False, "rowid": rowid})
    return out


def store_sessions(store, limit=60):
    rows = store.query("SELECT id, started, ended, source, iface, network "
                       "FROM sessions ORDER BY started DESC LIMIT ?",
                       (limit,))
    return [{"id": r[0], "started": r[1], "ended": r[2], "source": r[3],
             "iface": r[4], "network": r[5]} for r in rows]


def session_label(s):
    end = fmt_clock(s["ended"]) if s.get("ended") else "running"
    net = f" · {s['network']}" if s.get("network") else ""
    return (f"{fmt_clock(s['started'], True)} → {end}{net} "
            f"[#{s['id']}]")


def session_profile(store, sid):
    """Devices, websites and event counts recorded for one session."""
    devices = {}
    for subj, data in store.query(
            "SELECT subject, data FROM observations WHERE session=? AND "
            "kind IN (?,?,?,?,?) LIMIT 50000",
            (sid, OBS_KIND_CODES["dhcp_request"], OBS_KIND_CODES["dhcp_ack"],
             OBS_KIND_CODES["mdns"], OBS_KIND_CODES["arp_reply"],
             OBS_KIND_CODES["nbns"])):
        name = devices.get(subj, "")
        if not name and data:
            with contextlib.suppress(ValueError, TypeError):
                d = json.loads(data)
                name = d.get("hostname") or d.get("name") or ""
        devices[subj] = name
    for (subj,) in store.query("SELECT DISTINCT subject FROM observations "
                               "WHERE session=? AND subject NOT LIKE 'site:%' "
                               "AND subject NOT LIKE 'flow:%' LIMIT 20000",
                               (sid,)):
        devices.setdefault(subj, "")
    sites = {}
    for dom, assoc in store.query("SELECT domain, assoc FROM site_ties "
                                  "WHERE session=?", (sid,)):
        root = registrable_domain(dom)
        sites[root] = better_assoc(assoc, sites.get(root, ""))
    kinds = dict(store.query("SELECT kind, COUNT(*) FROM events WHERE "
                             "session=? GROUP BY kind", (sid,)))
    return {"devices": devices, "sites": sites, "events": kinds}


def compare_sessions(store, a, b):
    """What differs between session a (older) and b (newer)."""
    pa, pb = session_profile(store, a), session_profile(store, b)
    da, db = set(pa["devices"]), set(pb["devices"])
    sa, sb = set(pa["sites"]), set(pb["sites"])
    return {"new_devices": sorted(db - da), "gone_devices": sorted(da - db),
            "both_devices": sorted(da & db),
            "new_sites": sorted(sb - sa), "gone_sites": sorted(sa - sb),
            "names": {**pa["devices"], **pb["devices"]},
            "events_a": pa["events"], "events_b": pb["events"]}


class PacketRing:
    """Optional on-disk history of raw packets: pcap segments in the data
    folder, oldest deleted first so it never exceeds its size cap. Lets a
    proof chip open a packet that has already left memory. Off by
    default; never uploaded."""

    SEGMENT_BYTES = 8 * 1024 * 1024

    def __init__(self, folder, cap_mb=200, store=None, session=0):
        self.folder = folder
        self.cap = max(20, int(cap_mb)) * 1024 * 1024
        self.store = store
        self.session = session
        self.epoch = 0
        self.q = queue.Queue(maxsize=50000)
        self.dropped = 0
        self.written = 0
        self.index = []       # [first_no, last_no, path, epoch, bytes]
        self._seg = None
        self._stop = False
        self._lock = threading.Lock()
        os.makedirs(folder, exist_ok=True)
        # segments of earlier runs still count toward the size cap
        old = []
        with contextlib.suppress(OSError):
            for name in os.listdir(folder):
                if name.startswith("seg-") and name.endswith(".pcap"):
                    path = os.path.join(folder, name)
                    with contextlib.suppress(OSError):
                        st = os.stat(path)
                        old.append((st.st_mtime, path, st.st_size))
        for _m, path, size in sorted(old):
            self.index.append([-1, -2, path, -1, size])
        self._enforce_cap()
        self._thread = threading.Thread(target=self._run, daemon=True,
                                        name="packet-ring")
        self._thread.start()

    def new_epoch(self):
        """Packet numbers restart (Clear / new model): keep segments apart."""
        try:
            self.q.put_nowait(("epoch",))
        except queue.Full:
            self.dropped += 1

    def put(self, no, raw, ts, lt):
        try:
            self.q.put_nowait((no, raw, ts, lt))
            return True
        except queue.Full:
            self.dropped += 1
            return False

    def _open(self, no, ts, lt):
        name = f"seg-{self.session}-{self.epoch}-{no:012d}.pcap"
        path = os.path.join(self.folder, name)
        f = open(path, "wb")
        f.write(struct.pack("<IHHiIII", 0xa1b2c3d4, 2, 4, 0, 0, 262144, lt))
        self._seg = {"f": f, "path": path, "first": no, "last": no - 1,
                     "t0": ts, "t1": ts, "lt": lt, "bytes": 24}

    def _close(self):
        seg, self._seg = self._seg, None
        if seg is None:
            return
        with contextlib.suppress(OSError):
            seg["f"].close()
        if seg["last"] < seg["first"]:
            with contextlib.suppress(OSError):
                os.remove(seg["path"])
            return
        self.index.append([seg["first"], seg["last"], seg["path"],
                           self.epoch, seg["bytes"]])
        if self.store is not None:
            self.store.write_segment(seg["first"], seg["last"], seg["t0"],
                                     seg["t1"], seg["path"], seg["bytes"],
                                     seg["lt"])
        self._enforce_cap()

    def _enforce_cap(self):
        total = sum(e[4] for e in self.index)
        while self.index and total > self.cap:
            old = self.index.pop(0)
            total -= old[4]
            with contextlib.suppress(OSError):
                os.remove(old[2])

    def _run(self):
        while True:
            try:
                item = self.q.get(timeout=0.5)
            except queue.Empty:
                if self._stop:
                    break
                continue
            if item is None:
                break
            try:
                with self._lock:
                    self._handle(item)
            except (OSError, ValueError, TypeError, struct.error) as e:
                LOG.warning("packet history: %s", e)
                with self._lock:
                    with contextlib.suppress(Exception):
                        self._seg["f"].close()
                    self._seg = None
        with self._lock:
            self._close()

    def _handle(self, item):
        if item[0] == "epoch":
            self._close()
            self.epoch += 1
            return
        if item[0] == "flush":
            if self._seg is not None:
                self._seg["f"].flush()
            item[1].set()
            return
        no, raw, ts, lt = item
        seg = self._seg
        if seg is None or seg["lt"] != lt or no != seg["last"] + 1 \
                or seg["bytes"] > self.SEGMENT_BYTES:
            self._close()
            self._open(no, ts, lt)
            seg = self._seg
        ts = float(ts)
        sec = int(ts)
        usec = min(999999, max(0, int(round((ts - sec) * 1e6))))
        seg["f"].write(struct.pack("<IIII", sec & 0xffffffff, usec,
                                   len(raw), len(raw)))
        seg["f"].write(raw)
        seg["last"], seg["t1"] = no, ts
        seg["bytes"] += 16 + len(raw)
        self.written += 1

    def flush(self, timeout=3.0):
        """Wait until everything queued so far is on disk."""
        ev = threading.Event()
        try:
            self.q.put(("flush", ev), timeout=1)
        except queue.Full:
            return False
        return ev.wait(timeout)

    def find(self, no, epoch=None):
        """(raw, ts, linktype) of packet `no` from disk, or None."""
        with self._lock:
            epoch = self.epoch if epoch is None else epoch
            seg = self._seg
            candidates = [e[:] for e in reversed(self.index)
                          if e[3] == epoch and e[0] <= no <= e[1]]
            if seg is not None and epoch == self.epoch and \
                    seg["first"] <= no <= seg["last"]:
                with contextlib.suppress(OSError, ValueError):
                    seg["f"].flush()
                candidates.insert(0, [seg["first"], seg["last"], seg["path"],
                                      epoch, 0])
        for first, last, path, _ep, _b in candidates:
            try:
                for i, frame in enumerate(iter_raw_capture(path)):
                    if first + i == no:
                        return frame
                    if first + i > last:
                        break
            except (OSError, ValueError, struct.error):
                continue
        return None

    def size_bytes(self):
        seg = self._seg
        return sum(e[4] for e in self.index) + (seg["bytes"] if seg else 0)

    def stop(self, wait=3.0):
        self._stop = True
        with contextlib.suppress(queue.Full):
            self.q.put_nowait(None)
        if wait:
            self._thread.join(wait)


def digest_summary(dg):
    parts = []
    for key, one, many in (("new_devices", "new device", "new devices"),
                           ("new_sites", "new website", "new websites"),
                           ("left", "device left", "devices left"),
                           ("alerts", "warning", "warnings")):
        n = len(dg[key])
        if n:
            parts.append(f"{n} {one if n == 1 else many}")
    return " · ".join(parts) if parts else "Nothing new."


