def run_gui_test(live=False):
    """Returns 0 on success. Prints a step-by-step report."""
    global PATHS
    tmp = tempfile.mkdtemp(prefix="mw_guitest_")
    os.environ["MINIWIRESHARK_DATA"] = tmp
    PATHS = AppPaths()
    setup_logging()
    load_scapy()
    _patch_dialogs_for_tests()
    results = []
    ctx = TestContext(tmp, True)
    cfg = ctx.cfg({"general.auto_start_capture": False,
                   "updates.check_automatically": False,
                   "privacy.auto_download_reference": False,
                   "history.enabled": True,
                   "history.retention": "7 days"})
    cfg.save()
    root = tk.Tk()
    gw, ips, macs, nets = scenario_identity()
    app = MiniWireshark(root, "", set(), set(), "", config=cfg)

    def step(name, fn):
        t0 = time.perf_counter()
        try:
            fn()
            results.append(("PASS", name, ""))
        except Exception as e:                       # noqa: BLE001
            results.append(("FAIL", name, f"{type(e).__name__}: {e}\n" +
                            traceback.format_exc(limit=6)))
        print(f"  [{results[-1][0]}] {name} "
              f"({(time.perf_counter() - t0) * 1000:.0f} ms)", flush=True)

    frames = ctx.frames()
    pcap = ctx.path("scenario.pcap")
    write_raw_pcap(pcap, frames)

    def s_import():
        app.import_pcap_path(pcap)
        ok = _gui_pump(root, 0.5, lambda: app.importer is None and
                       app.data_mode == "offline" and
                       app.model.count >= len(frames), timeout=60)
        assert ok, f"import stalled at {app.model.count}/{len(frames)}"
        _gui_pump(root, 2.2)
        fails = golden_checks(app.model)
        assert not fails, "; ".join(fails)

    def s_tabs():
        for name, tab in app.tabs.items():
            app._select_tab(name)
            _gui_pump(root, 0.05)
            tab.refresh()

    def s_modes_and_themes():
        for mode in ("Advanced", "Beginner", "Advanced"):
            app.mode_ui_var.set(mode)
            app._on_ui_mode_change()
            _gui_pump(root, 0.05)
        for theme, hc in (("Dark", False), ("Dark", True), ("Light", True),
                          ("Light", False), ("Dark", False)):
            app._apply_theme(theme, hc)
            for name in app.tabs:
                app._select_tab(name)
                _gui_pump(root, 0.02)
        leaks = dark_theme_leaks(root)
        app._apply_theme("Light", False)
        assert not leaks, f"{len(leaks)} light widgets in Dark: " + \
            "; ".join(leaks[:6])

    def s_details():
        m = app.model
        for key in list(m.registry.by_key)[:12]:
            app.show_device(key)
        for dom in list(m.websites)[:6]:
            app.show_website(dom)
        for ip in list(m.remote_hosts)[:4]:
            app.show_remote(ip)
        for f in list(m.flows.all_flows())[:4]:
            app.show_flow(f.fid)
        for aid in list(m.alerts.order)[:4]:
            app.show_alert(aid)
        _gui_pump(root, 0.2)
        for w in root.winfo_children():
            if isinstance(w, tk.Toplevel):
                w.destroy()

    def s_settings():
        app._open_settings()
        _gui_pump(root, 0.2)
        sw = app._settings_win
        for page in SETTINGS_PAGES:
            sw.show_page(page["id"])
            _gui_pump(root, 0.02)
        sw.win.destroy()
        app.open_diagnostics()
        _gui_pump(root, 0.3)
        app._diag_win.win.destroy()

    def s_search():
        for q in ("example", "ip:192.168.1.23", "port:443", "device:tv",
                  "alert:cleartext"):
            res = app.search_results(q)
            assert isinstance(res, (list, dict))

    def s_demo():
        app.start_demo()
        _gui_pump(root, 2.5)
        assert app.data_mode == "demo" and app.model.demo
        app.stop_demo()
        _gui_pump(root, 0.3)
        assert not any(d.ip.startswith("192.168.50.") for d in
                       app.model.registry.by_key.values() if d.ip)

    for name, fn in (("import scenario capture (golden checks)", s_import),
                     ("visit every tab", s_tabs),
                     ("modes and themes (dark leak audit)",
                      s_modes_and_themes),
                     ("detail views", s_details),
                     ("settings and diagnostics", s_settings),
                     ("global search", s_search)):
        step(name, fn)
    for name, fn in GUI_TEST_STEPS:
        step(name, lambda fn=fn: fn(app, ctx))
    step("demo mode starts and leaves no trace", s_demo)

    def s_close():
        app._on_close()
        time.sleep(0.5)
        bad = [t.name for t in threading.enumerate()
               if t is not threading.main_thread() and not t.daemon]
        assert not bad, f"non-daemon threads left: {bad}"
    step("clean shutdown", s_close)
    failed = [r for r in results if r[0] == "FAIL"]
    print(f"\nGUI test: {len(results) - len(failed)} passed / "
          f"{len(failed)} failed")
    for _s, name, msg in failed:
        print(f"\nFAILED: {name}\n{msg}")
    shutil.rmtree(tmp, ignore_errors=True)
    return 1 if failed else 0


def write_raw_pcap(path, frames):
    """Write (raw, ts, linktype) frames to a classic pcap file (stdlib)."""
    lt = frames[0][2] if frames else 1
    with open(path, "wb") as f:
        f.write(struct.pack("<IHHiIII", 0xa1b2c3d4, 2, 4, 0, 0, 262144, lt))
        for raw, ts, _lt in frames:
            sec = int(ts)
            usec = int(round((ts - sec) * 1e6)) % 1000000
            f.write(struct.pack("<IIII", sec, usec, len(raw), len(raw)))
            f.write(raw)


def startup_sanity_checks():
    """Cheap checks at GUI start (the full suite is --self-test)."""
    problems = []
    flat = config_defaults_flat()
    for key in settings_schema_keys():
        if key not in flat:
            problems.append(f"setting without default: {key}")
    for name, table in PALETTES.items():
        if len(set(table.values())) != len(table):
            problems.append(f"palette {name} is not one-to-one")
    for p in problems:
        LOG.warning("sanity: %s", p)
    return problems



# ============================================================================
#  21.  Application entry point
# ============================================================================
def detect_gateway_and_self():
    """Return (gateway_ip, my_ips, my_macs, default_iface_name)."""
    gw = ""
    my_ips, my_macs = set(), set()
    default_iface_name = ""
    try:
        try:
            # scapy's route() returns (iface, output_ip, gateway_ip)
            def_iface, my_ip, gw_ip = conf.route.route("0.0.0.0")
            gw = gw_ip if gw_ip and gw_ip != "0.0.0.0" else ""
            default_iface_name = iface_name(def_iface)
            if my_ip and my_ip != "0.0.0.0":
                my_ips.add(my_ip)
        except Exception as e:                       # noqa: BLE001
            LOG.info("default route lookup failed: %s", e)
        for route in conf.route.routes:
            with contextlib.suppress(ValueError, TypeError, IndexError):
                addr = route[4]
                if addr and addr not in ("0.0.0.0", "127.0.0.1"):
                    my_ips.add(addr)
        for iface in conf.ifaces.values():
            mac = getattr(iface, "mac", None)
            if mac and is_unicast_mac(mac):
                my_macs.add(mac.lower())
    except Exception as e:                           # noqa: BLE001
        LOG.warning("identity detection failed: %s", e)
    return gw, my_ips, my_macs, default_iface_name


def _install_thread_excepthook():
    def hook(args):
        if args.exc_type is SystemExit:
            return
        LOG.error("unhandled exception in thread %s:\n%s",
                  getattr(args.thread, "name", "?"),
                  "".join(traceback.format_exception(
                      args.exc_type, args.exc_value, args.exc_traceback)))
    if hasattr(threading, "excepthook"):
        threading.excepthook = hook


def main():
    setup_logging()
    LOG.info("MiniWireshark %s starting (python %s at %s, %s, admin=%s, "
             "stage=%s)", SCRIPT_VERSION, platform.python_version(),
             sys.executable, platform.platform(), is_admin(),
             MW_STAGE or "launcher")
    _install_thread_excepthook()
    install_gui_gate()
    rolled = rollback_update_if_needed()
    if MW_STAGE == "app":
        RuntimeManager().apply_pending_switch()
    cfg = AppConfig()
    root = tk.Tk()
    root.title("MiniWireshark")
    root.minsize(640, 520)
    _center_window(root, 760, 680)
    base_ttk_style()
    if rolled:
        messagebox.showwarning("Update rolled back", rolled)

    loader = LoaderWindow(root, cfg)
    loader.pack(fill="both", expand=True)
    root.configure(background=loader.bg)
    root.update()
    PIP_ASK[0] = lambda: loader.ask("pip_system") == "yes"

    ok, err = run_bootstrap(loader)
    PIP_ASK[0] = None
    if not ok:
        loader.show_fatal(err)
        root.mainloop()
        return
    if loader.handoff:
        # the private Python is ready: continue inside it
        loader.post_status("Starting inside the private Python …")
        loader.pump()
        with contextlib.suppress(tk.TclError):
            root.destroy()
        if runtime_handoff() is None:
            _fatal_dialog("MiniWireshark", "The private Python was installed "
                          "but could not be started. Start MiniWireshark "
                          "again; it will use your current Python if the "
                          "problem persists.")
        return

    loader.post_status("Loading the packet engine ...")
    loader.post_progress(100)
    loader.pump()
    try:
        load_scapy()
    except Exception as e:                           # noqa: BLE001
        LOG.exception("scapy import")
        loader.show_fatal(f"Could not load the capture engine (scapy): {e}\n\n"
                          f"{traceback.format_exc()}")
        root.mainloop()
        return
    loader.post_status("Looking at your network adapters ...")
    loader.pump()
    gw, my_ips, my_macs, default_iface_name = detect_gateway_and_self()
    LOG.info("default iface=%s gateway=%s my_ips=%s", default_iface_name, gw,
             sorted(my_ips))
    startup_sanity_checks()
    t_ready = time.perf_counter() - _T_START
    LAUNCH_TIMES["ready"] = t_ready

    action = None
    first_time = cfg.get("general.welcome_version", "") != SCRIPT_VERSION
    if START_IN_DEMO:
        action = "demo"
    elif cfg.get("general.show_welcome", True) or first_time:
        health = "healthy"
        st = RuntimeManager().status()
        if not st["running_inside"] and RuntimeManager().plan()[
                "supported"] and NO_RUNTIME_FLAG not in sys.argv:
            health = "degraded"
        summary = welcome_summary(cfg)
        action = loader.show_welcome(summary, health, first_time)
        if action == "exit":
            with contextlib.suppress(tk.TclError):
                root.destroy()
            return

    loader.destroy()
    root.resizable(True, True)
    root.title("MiniWireshark")
    try:
        MiniWireshark(root, gw, my_ips, my_macs, default_iface_name,
                      config=cfg, start_action=action)
    except Exception:                                # noqa: BLE001
        text = traceback.format_exc()
        LOG.error("startup error:\n%s", text)
        rolled = rollback_update_if_needed(force=True) \
            if os.path.exists(PATHS.update_marker) else ""
        messagebox.showerror("Startup error",
                             (rolled + "\n\n" if rolled else "") +
                             "MiniWireshark couldn't start its window.\n\n" +
                             text[-2500:] + f"\n\nLog: {PATHS.log_file}")
        root.destroy()
        return
    root.mainloop()
    LOG.info("MiniWireshark closed")


def _center_window(win, w, h):
    try:
        sw, sh = win.winfo_screenwidth(), win.winfo_screenheight()
        w, h = min(w, sw - 40), min(h, sh - 80)
        win.geometry(f"{w}x{h}+{max(0, (sw - w) // 2)}+"
                     f"{max(0, (sh - h) // 3)}")
    except tk.TclError:
        pass


def base_ttk_style():
    s = ttk.Style()
    with contextlib.suppress(tk.TclError):
        s.theme_use("clam")
    s.configure("TButton", padding=(10, 6))
    s.configure("Accent.TButton", padding=(14, 8),
                font=("TkDefaultFont", 11, "bold"), foreground="#ffffff",
                background="#2b7de9")
    s.map("Accent.TButton", background=[("active", "#1f66c7"),
                                        ("disabled", "#9bb8e8")])
    return s


def welcome_summary(cfg):
    """One line for the Welcome Center: last network, history, setup."""
    parts = []
    nets = NetworkProfiles(PATHS.networks)
    allnets = nets.all()
    if allnets:
        fp, prof = allnets[0]
        parts.append(f"Last network: {prof.get('name', '?')}"
                     f"{' (trusted)' if prof.get('trusted') else ' (quiet)'}")
    st = RuntimeManager().status()
    if st["running_inside"]:
        parts.append(f"Private Python {platform.python_version()}")
    else:
        parts.append(f"Python {platform.python_version()}")
    if cfg.get("history.enabled", False):
        parts.append("history on")
    return " · ".join(parts)


if __name__ == "__main__":
    if SELF_TEST_MODE:
        setup_logging()
        print(f"MiniWireshark {SCRIPT_VERSION} self-test")
        sys.exit(run_self_tests())
    if GUI_TEST_MODE:
        print(f"MiniWireshark {SCRIPT_VERSION} GUI test")
        sys.exit(run_gui_test(live="--live" in sys.argv))
    if BENCH_MODE:
        setup_logging()
        for k, v in bench_report().items():
            print(f"  {k:28s} {v:12.1f}")
        sys.exit(0)
    try:
        main()
    except KeyboardInterrupt:
        pass
    except Exception:                                # noqa: BLE001
        LOG.exception("fatal error")
        _fatal_dialog("MiniWireshark stopped unexpectedly",
                      traceback.format_exc()[-2500:] +
                      f"\n\nDetails were written to {PATHS.log_file}")
        raise
